def getAllPages(graphId, status=None, isJournal=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- request logging + rate/quota helpers ----
    def _get_logs():
        return _load("request_logs.json")

    def _save_logs(rows):
        _save("request_logs.json", rows)

    def _log_call(status_code, latency_ms, meta=None):
        rows = _get_logs()
        rows.append({
            "id": f"rql_{int(time.time()*1000)}_{len(rows)+1}",
            "endpoint": "getAllPages",
            "graph_id": graphId,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": now,
            "meta": meta or {}
        })
        _save_logs(rows)

    def _enforce_limits():
        rows = _get_logs()
        # Simple observable dynamics: 120 req/min global; 5000 req/day global
        ts_now = datetime.datetime.fromisoformat(now.replace("Z", "+00:00"))
        per_min = 0
        per_day = 0
        for r in rows[-10000:]:
            try:
                ts = datetime.datetime.fromisoformat(r.get("timestamp", "").replace("Z", "+00:00"))
            except Exception:
                continue
            delta = (ts_now - ts).total_seconds()
            if 0 <= delta <= 60:
                per_min += 1
            if 0 <= delta <= 86400:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded (120 requests per minute).")
        if per_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded (5000 requests per day).")
        return None

    # Enforce rate/quota before work
    lim_err = _enforce_limits()
    if lim_err:
        _log_call(lim_err["error"]["code"], (time.time() - t0) * 1000)
        return lim_err

    # ---- validation ----
    if not isinstance(graphId, str) or not re.match(r"^lsg_[0-9A-Za-z]+$", graphId):
        e = _err("VALIDATION_ERROR", "graphId is malformed.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted", "archived"):
            e = _err("VALIDATION_ERROR", "status must be one of: active, deleted, archived.")
            _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
            return e

    if isJournal is not None and not isinstance(isJournal, bool):
        e = _err("VALIDATION_ERROR", "isJournal must be a boolean.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 200):
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e

    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e

    if sort is None:
        sort = "updated_at"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "title"):
        e = _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, title.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e

    if order is None:
        order = "desc" if sort in ("updated_at", "created_at") else "asc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "order must be one of: asc, desc.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e

    # ---- graph resolution rules ----
    graphs = _load("graphs.json")
    g = next((x for x in graphs if x.get("id") == graphId), None)
    if not g:
        e = _err("NOT_FOUND", "Graph not found.")
        _log_call("NOT_FOUND", (time.time() - t0) * 1000)
        return e

    active_graphs = [x for x in graphs if x.get("status") == "active"]
    if len(active_graphs) != 1 or active_graphs[0].get("id") != graphId:
        # Business rule: all tools operate against exactly one active graph
        if len(active_graphs) == 0:
            e = _err("UNAUTHORIZED", "No active graph is configured for this operation.")
        elif len(active_graphs) > 1:
            e = _err("UNAUTHORIZED", "Multiple active graphs exist; cannot disambiguate.")
        else:
            e = _err("UNAUTHORIZED", "Requested graph is not the active graph.")
        _log_call(e["error"]["code"], (time.time() - t0) * 1000)
        return e

    pages = _load("pages.json")

    # Default behavior: active pages only unless caller asks otherwise (business rule)
    eff_status = status if status is not None else "active"
    rows = [p for p in pages if p.get("graph_id") == graphId and p.get("status") == eff_status]

    if isJournal is not None:
        rows = [p for p in rows if bool(p.get("is_journal")) == isJournal]

    # sorting
    reverse = (order == "desc")
    def _key(p):
        if sort == "title":
            return (p.get("title_norm") or "").lower()
        # timestamps are ISO strings; lexicographic works
        return p.get(sort) or ""
    rows.sort(key=_key, reverse=reverse)

    # pagination with opaque cursor as integer offset
    start = 0
    if cursor:
        if not cursor.startswith("off_"):
            e = _err("VALIDATION_ERROR", "cursor is invalid.")
            _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
            return e
        try:
            start = int(cursor.split("_", 1)[1])
        except Exception:
            e = _err("VALIDATION_ERROR", "cursor is invalid.")
            _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
            return e
        if start < 0:
            e = _err("VALIDATION_ERROR", "cursor is invalid.")
            _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
            return e

    total = len(rows)
    page_rows = rows[start:start + limit]
    next_off = start + len(page_rows)
    has_more = next_off < total
    next_cursor = f"off_{next_off}" if has_more else None

    # shape result (avoid exposing huge fields if present)
    def _proj(p):
        return {
            "id": p.get("id"),
            "graph_id": p.get("graph_id"),
            "title": p.get("title"),
            "title_norm": p.get("title_norm"),
            "is_journal": p.get("is_journal"),
            "journal_date": p.get("journal_date"),
            "properties": p.get("properties") or {},
            "content_plaintext": p.get("content_plaintext") or "",
            "status": p.get("status"),
            "created_at": p.get("created_at"),
            "updated_at": p.get("updated_at"),
        }

    out = {
        "data": [ _proj(p) for p in page_rows ],
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }
    _log_call("OK", (time.time() - t0) * 1000, meta={"returned": len(page_rows), "total": total})
    return out

def getPage(graphId, pageId=None, title=None, includeBlocks=None, blocksLimit=None, blocksCursor=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getPage"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return None

    def _append_log(status_code, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rql_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "graph_id": graphId,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        usage = _load("usage.json")
        if not isinstance(usage, dict):
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        per_min = usage.get("rate_limit_per_minute")
        quota_total = usage.get("quota_calls_total")
        calls_total = usage.get("calls_total")

        now_dt = datetime.datetime.now(datetime.timezone.utc)
        if isinstance(per_min, int) and per_min > 0:
            cutoff = now_dt - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs[-20000:]:
                if not isinstance(r, dict):
                    continue
                dt = _parse_iso(r.get("timestamp") or r.get("ts"))
                if dt and dt >= cutoff:
                    cnt += 1
            if cnt >= per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(quota_total, int) and quota_total >= 0:
            if not isinstance(calls_total, int):
                calls_total = 0
            if calls_total >= quota_total:
                return _err("QUOTA_EXCEEDED", "Quota exceeded")
        return None

    def _usage_bump(status_code):
        usage = _load("usage.json")
        if isinstance(usage, dict):
            usage["calls_total"] = int(usage.get("calls_total") or 0) + 1
            by_ep = usage.get("calls_by_endpoint")
            if not isinstance(by_ep, dict):
                by_ep = {}
            by_ep[endpoint] = int(by_ep.get(endpoint) or 0) + 1
            usage["calls_by_endpoint"] = by_ep
            if status_code and str(status_code).startswith("2"):
                usage["calls_succeeded"] = int(usage.get("calls_succeeded") or 0) + 1
            else:
                usage["calls_failed"] = int(usage.get("calls_failed") or 0) + 1
            _save("usage.json", usage)

    # Validate
    if not isinstance(graphId, str) or not re.match(r"^lsg_[0-9A-Za-z]+$", graphId):
        err = _err("VALIDATION_ERROR", "graphId is malformed.", field="graphId")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    if (pageId is None and title is None) or (pageId is not None and title is not None):
        err = _err("VALIDATION_ERROR", "Provide exactly one of pageId or title.", field="pageId/title")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    if pageId is not None:
        if not isinstance(pageId, str):
            err = _err("VALIDATION_ERROR", "pageId must be a string.", field="pageId")
            _append_log("400", {"error": err["error"]})
            _usage_bump("400")
            return err
        # Relax: some clients pass non-lsp ids; treat as not found instead of malformed unless it is clearly not an id-like string
        if not re.match(r"^[A-Za-z0-9_:-]{6,}$", pageId):
            err = _err("VALIDATION_ERROR", "pageId is malformed.", field="pageId")
            _append_log("400", {"error": err["error"]})
            _usage_bump("400")
            return err

    if title is not None and not isinstance(title, str):
        err = _err("VALIDATION_ERROR", "title must be a string.", field="title")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    if includeBlocks is not None and not isinstance(includeBlocks, bool):
        err = _err("VALIDATION_ERROR", "includeBlocks must be a boolean.", field="includeBlocks")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    if blocksLimit is not None:
        if not isinstance(blocksLimit, int):
            err = _err("VALIDATION_ERROR", "blocksLimit must be an integer.", field="blocksLimit")
            _append_log("400", {"error": err["error"]})
            _usage_bump("400")
            return err
        if blocksLimit < 1 or blocksLimit > 500:
            err = _err("VALIDATION_ERROR", "blocksLimit is out of range (1–500).", field="blocksLimit")
            _append_log("400", {"error": err["error"]})
            _usage_bump("400")
            return err

    if blocksCursor is not None and not isinstance(blocksCursor, str):
        err = _err("VALIDATION_ERROR", "blocksCursor must be a string.", field="blocksCursor")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    lim_err = _enforce_limits()
    if lim_err:
        _append_log("429", {"error": lim_err["error"]})
        _usage_bump("429")
        return lim_err

    graphs = _load("graphs.json")
    pages = _load("pages.json")
    blocks = _load("blocks.json")

    # AuthZ/context: accept explicit graphId if it exists and is active; otherwise fall back to the single active graph rule
    graph_row = None
    if isinstance(graphs, list):
        for g in graphs:
            if isinstance(g, dict) and g.get("id") == graphId:
                graph_row = g
                break
    if not graph_row:
        err = _err("NOT_FOUND", "Graph not found.", field="graphId")
        _append_log("404", {"error": err["error"]})
        _usage_bump("404")
        return err

    # Find page
    page_row = None
    if isinstance(pages, list):
        if pageId is not None:
            for p in pages:
                if isinstance(p, dict) and p.get("id") == pageId and p.get("graph_id") == graphId and p.get("status") == "active":
                    page_row = p
                    break
        else:
            title_norm = " ".join(title.strip().lower().split())
            for p in pages:
                if not isinstance(p, dict):
                    continue
                if p.get("graph_id") != graphId or p.get("status") != "active":
                    continue
                if p.get("title_norm") == title_norm:
                    page_row = p
                    break

    if not page_row:
        # reads with no match => NOT_FOUND for single resource
        err = _err("NOT_FOUND", "Page not found.")
        _append_log("404", {"error": err["error"]})
        _usage_bump("404")
        return err

    resp = {"page": page_row}

    # Include blocks
    if includeBlocks:
        limit_val = blocksLimit if blocksLimit is not None else 50
        # Collect active blocks for page
        page_blocks = []
        if isinstance(blocks, list):
            for b in blocks:
                if isinstance(b, dict) and b.get("graph_id") == graphId and b.get("page_id") == page_row.get("id") and b.get("status") == "active":
                    page_blocks.append(b)

        # stable sort by order_index then created_at then id
        def _key(b):
            oi = b.get("order_index")
            try:
                oi = int(oi)
            except Exception:
                oi = 0
            ca = _parse_iso(b.get("created_at") or "") or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (oi, ca, b.get("id") or "")
        page_blocks.sort(key=_key)

        start = 0
        if blocksCursor:
            # cursor is block id; start after it if present
            for i, b in enumerate(page_blocks):
                if b.get("id") == blocksCursor:
                    start = i + 1
                    break

        items = page_blocks[start:start + limit_val]
        next_cursor = items[-1].get("id") if items and (start + limit_val) < len(page_blocks) else None
        resp["blocks"] = {
            "data": items,
            "total": len(page_blocks),
            "has_more": next_cursor is not None,
            "next_cursor": next_cursor
        }

    _append_log("200", {"page_id": page_row.get("id"), "includeBlocks": bool(includeBlocks)})
    _usage_bump("200")
    return resp

def getJournalSummary(graphId, startDate=None, endDate=None, timezone=None, includeLinks=None, forceRecompute=None, **_extra):
    import json, os, datetime, re, time
    try:
        from zoneinfo import ZoneInfo
    except Exception:
        ZoneInfo = None

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_logs():
        return _load("request_logs.json")

    def _save_logs(rows):
        _save("request_logs.json", rows)

    def _log_call(status_code, latency_ms, meta=None):
        rows = _get_logs()
        rows.append({
            "id": f"rql_{int(time.time()*1000)}_{len(rows)+1}",
            "endpoint": "getJournalSummary",
            "graph_id": graphId,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": now,
            "meta": meta or {}
        })
        _save_logs(rows)

    def _enforce_limits():
        rows = _get_logs()
        ts_now = datetime.datetime.fromisoformat(now.replace("Z", "+00:00"))
        per_min = 0
        per_day = 0
        for r in rows[-10000:]:
            try:
                ts = datetime.datetime.fromisoformat(r.get("timestamp", "").replace("Z", "+00:00"))
            except Exception:
                continue
            delta = (ts_now - ts).total_seconds()
            if 0 <= delta <= 60:
                per_min += 1
            if 0 <= delta <= 86400:
                per_day += 1
        if per_min >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded (60 requests per minute).")
        if per_day >= 2000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded (2000 requests per day).")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log_call(lim_err["error"]["code"], (time.time() - t0) * 1000)
        return lim_err

    if not isinstance(graphId, str) or not re.match(r"^lsg_[0-9A-Za-z]+$", graphId):
        e = _err("VALIDATION_ERROR", "graphId is malformed.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e

    if not isinstance(startDate, str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", startDate):
        e = _err("VALIDATION_ERROR", "startDate is missing or invalid (expected YYYY-MM-DD).")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e
    if not isinstance(endDate, str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", endDate):
        e = _err("VALIDATION_ERROR", "endDate is missing or invalid (expected YYYY-MM-DD).")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e

    try:
        sd = datetime.date.fromisoformat(startDate)
        ed = datetime.date.fromisoformat(endDate)
    except Exception:
        e = _err("VALIDATION_ERROR", "startDate/endDate are invalid dates.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e
    if sd > ed:
        e = _err("VALIDATION_ERROR", "startDate must be on or before endDate.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e

    if includeLinks is None:
        includeLinks = False
    if not isinstance(includeLinks, bool):
        e = _err("VALIDATION_ERROR", "includeLinks must be a boolean.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e

    if forceRecompute is None:
        forceRecompute = False
    if not isinstance(forceRecompute, bool):
        e = _err("VALIDATION_ERROR", "forceRecompute must be a boolean.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e

    graphs = _load("graphs.json")
    g = next((x for x in graphs if x.get("id") == graphId), None)
    if not g:
        e = _err("NOT_FOUND", "Graph not found.")
        _log_call("NOT_FOUND", (time.time() - t0) * 1000)
        return e

    active_graphs = [x for x in graphs if x.get("status") == "active"]
    if len(active_graphs) != 1 or active_graphs[0].get("id") != graphId:
        if len(active_graphs) == 0:
            e = _err("UNAUTHORIZED", "No active graph is configured for this operation.")
        elif len(active_graphs) > 1:
            e = _err("UNAUTHORIZED", "Multiple active graphs exist; cannot disambiguate.")
        else:
            e = _err("UNAUTHORIZED", "Requested graph is not the active graph.")
        _log_call(e["error"]["code"], (time.time() - t0) * 1000)
        return e

    tz_name = timezone or g.get("timezone")
    if not isinstance(tz_name, str) or not tz_name:
        e = _err("VALIDATION_ERROR", "timezone is invalid.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e
    if ZoneInfo is None:
        # environment lacks zoneinfo; accept but don't validate strictly
        tz = None
    else:
        try:
            tz = ZoneInfo(tz_name)
        except Exception:
            e = _err("VALIDATION_ERROR", "timezone is not a recognized identifier.")
            _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
            return e

    # caching: analysis_runs with tool_name='getJournalSummary' and same input
    runs = _load("analysis_runs.json")
    cache_key = {
        "graph_id": graphId,
        "tool_name": "getJournalSummary",
        "startDate": startDate,
        "endDate": endDate,
        "timezone": tz_name,
        "includeLinks": includeLinks
    }
    if not forceRecompute:
        for r in reversed(runs):
            if r.get("graph_id") != graphId or r.get("tool_name") != "getJournalSummary":
                continue
            if r.get("status") != "succeeded":
                continue
            inp = r.get("input") or {}
            if (inp.get("startDate") == startDate and inp.get("endDate") == endDate and
                inp.get("timezone") == tz_name and bool(inp.get("includeLinks")) == includeLinks):
                out = {"data": r.get("result"), "analysis_run": r}
                _log_call("OK", (time.time() - t0) * 1000, meta={"cached": True})
                return out

    # compute summary
    pages = _load("pages.json")
    blocks = _load("blocks.json")
    links = _load("page_links.json")

    journal_pages = [p for p in pages
                     if p.get("graph_id") == graphId and p.get("status") == "active"
                     and p.get("is_journal") is True and isinstance(p.get("journal_date"), str)
                     and re.match(r"^\d{4}-\d{2}-\d{2}$", p.get("journal_date") or "")]
    # filter date range
    jp_in_range = []
    for p in journal_pages:
        try:
            d = datetime.date.fromisoformat(p.get("journal_date"))
        except Exception:
            continue
        if sd <= d <= ed:
            jp_in_range.append(p)

    jp_ids = {p["id"] for p in jp_in_range if isinstance(p.get("id"), str)}
    jb = [b for b in blocks if b.get("graph_id") == graphId and b.get("status") == "active" and b.get("page_id") in jp_ids]

    total_blocks = len(jb)
    total_chars = sum(len((b.get("content_plaintext") or "")) for b in jb)
    # tag stats from page_links link_type='tag' and blocks within the journal pages
    tag_edges = [e for e in links if e.get("graph_id") == graphId and e.get("link_type") == "tag" and e.get("source_block_id") in {b.get("id") for b in jb}]
    tag_counts = {}
    # need target page titles
    page_by_id = {p.get("id"): p for p in pages if p.get("graph_id") == graphId}
    for e in tag_edges:
        tid = e.get("target_page_id")
        tpage = page_by_id.get(tid) or {}
        ttitle = tpage.get("title") or tid
        tag_counts[ttitle] = tag_counts.get(ttitle, 0) + 1
    top_tags = sorted(tag_counts.items(), key=lambda kv: (-kv[1], str(kv[0]).lower()))[:20]
    top_tags = [{"tag": k, "count": v} for k, v in top_tags]

    # streaks: consecutive dates with at least 1 journal page
    dates_present = set()
    for p in jp_in_range:
        try:
            dates_present.add(datetime.date.fromisoformat(p.get("journal_date")))
        except Exception:
            pass
    streak = 0
    best = 0
    cur = 0
    d = sd
    while d <= ed:
        if d in dates_present:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
        d = d + datetime.timedelta(days=1)
    streak = best

    # Optional link/backlink stats limited to journal pages
    link_stats = None
    if includeLinks:
        # outbound links from journal blocks (wikilink/tag/property)
        outbound = [e for e in links if e.get("graph_id") == graphId and e.get("source_block_id") in {b.get("id") for b in jb}]
        outbound_count = len(outbound)
        unique_targets = len({e.get("target_page_id") for e in outbound if e.get("target_page_id")})
        link_stats = {
            "outbound_edges": outbound_count,
            "unique_targets": unique_targets,
            "tag_edges": len([e for e in outbound if e.get("link_type") == "tag"]),
            "wikilink_edges": len([e for e in outbound if e.get("link_type") == "wikilink"]),
            "property_edges": len([e for e in outbound if e.get("link_type") == "property"]),
        }

    summary_text = (
        f"Journal summary for {startDate} to {endDate} ({tz_name}). "
        f"Days with entries: {len(dates_present)}. "
        f"Total blocks: {total_blocks}. "
        f"Total characters: {total_chars}. "
        f"Longest streak: {streak} day(s)."
    )

    result = {
        "graph_id": graphId,
        "startDate": startDate,
        "endDate": endDate,
        "timezone": tz_name,
        "journal_pages": len(jp_in_range),
        "days_with_entries": len(dates_present),
        "total_blocks": total_blocks,
        "total_characters": total_chars,
        "longest_streak_days": streak,
        "top_tags": top_tags,
        "link_stats": link_stats,
        "summary": summary_text
    }

    # persist analysis run
    def _new_id(prefix, rows):
        return f"{prefix}_{int(time.time()*1000)}_{len(rows)+1}"

    run = {
        "id": _new_id("lsar", runs),
        "graph_id": graphId,
        "tool_name": "getJournalSummary",
        "status": "succeeded",
        "input": {"startDate": startDate, "endDate": endDate, "timezone": tz_name, "includeLinks": includeLinks},
        "result": result,
        "error_message": None,
        "started_at": now,
        "finished_at": now,
        "created_at": now,
        "updated_at": now
    }
    runs.append(run)
    _save("analysis_runs.json", runs)

    _log_call("OK", (time.time() - t0) * 1000, meta={"cached": False, "journal_pages": len(jp_in_range)})
    return {"data": result, "analysis_run": run}

def createPage(graphId, title, isJournal=None, journalDate=None, properties=None, contentMarkdown=None, status=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_logs():
        return _load("request_logs.json")

    def _save_logs(rows):
        _save("request_logs.json", rows)

    def _log_call(status_code, latency_ms, meta=None):
        rows = _get_logs()
        rows.append({
            "id": f"rql_{int(time.time()*1000)}_{len(rows)+1}",
            "endpoint": "createPage",
            "graph_id": graphId,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": now,
            "meta": meta or {}
        })
        _save_logs(rows)

    def _enforce_limits():
        rows = _get_logs()
        ts_now = datetime.datetime.fromisoformat(now.replace("Z", "+00:00"))
        per_min = 0
        per_day = 0
        for r in rows[-10000:]:
            try:
                ts = datetime.datetime.fromisoformat(r.get("timestamp", "").replace("Z", "+00:00"))
            except Exception:
                continue
            delta = (ts_now - ts).total_seconds()
            if 0 <= delta <= 60:
                per_min += 1
            if 0 <= delta <= 86400:
                per_day += 1
        if per_min >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded (60 requests per minute).")
        if per_day >= 1000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded (1000 requests per day).")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log_call(lim_err["error"]["code"], (time.time() - t0) * 1000)
        return lim_err

    if not isinstance(graphId, str) or not re.match(r"^lsg_[0-9A-Za-z]+$", graphId):
        e = _err("VALIDATION_ERROR", "graphId is malformed.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e

    if not isinstance(title, str) or not title.strip():
        e = _err("VALIDATION_ERROR", "title is empty or invalid.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e

    if isJournal is None:
        isJournal = False
    if not isinstance(isJournal, bool):
        e = _err("VALIDATION_ERROR", "isJournal must be a boolean.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e

    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in ("active", "deleted", "archived"):
        e = _err("VALIDATION_ERROR", "status must be one of: active, deleted, archived.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e

    if properties is None:
        properties = {}
    if not isinstance(properties, dict):
        e = _err("VALIDATION_ERROR", "properties must be an object.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e

    if contentMarkdown is not None and not isinstance(contentMarkdown, str):
        e = _err("VALIDATION_ERROR", "contentMarkdown must be a string.")
        _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
        return e

    if isJournal:
        if not isinstance(journalDate, str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", journalDate):
            e = _err("VALIDATION_ERROR", "journalDate is required and must be YYYY-MM-DD when isJournal is true.")
            _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
            return e
        try:
            datetime.date.fromisoformat(journalDate)
        except Exception:
            e = _err("VALIDATION_ERROR", "journalDate is invalid.")
            _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
            return e
    else:
        if journalDate is not None:
            e = _err("VALIDATION_ERROR", "journalDate must be null when isJournal is false.")
            _log_call("VALIDATION_ERROR", (time.time() - t0) * 1000)
            return e

    graphs = _load("graphs.json")
    g = next((x for x in graphs if x.get("id") == graphId), None)
    if not g:
        e = _err("NOT_FOUND", "Graph not found.")
        _log_call("NOT_FOUND", (time.time() - t0) * 1000)
        return e

    active_graphs = [x for x in graphs if x.get("status") == "active"]
    if len(active_graphs) != 1 or active_graphs[0].get("id") != graphId:
        if len(active_graphs) == 0:
            e = _err("UNAUTHORIZED", "No active graph is configured for this operation.")
        elif len(active_graphs) > 1:
            e = _err("UNAUTHORIZED", "Multiple active graphs exist; cannot disambiguate.")
        else:
            e = _err("UNAUTHORIZED", "Requested graph is not the active graph.")
        _log_call(e["error"]["code"], (time.time() - t0) * 1000)
        return e

    pages = _load("pages.json")
    blocks = _load("blocks.json")
    page_links = _load("page_links.json")

    def _norm(s):
        return " ".join((s or "").strip().lower().split())

    title_norm = _norm(title)

    # idempotent create: if page exists with same title_norm and status != deleted, return it
    existing = next((p for p in pages
                     if p.get("graph_id") == graphId and (p.get("title_norm") or "") == title_norm
                     and p.get("status") != "deleted"), None)
    if existing:
        _log_call("OK", (time.time() - t0) * 1000, meta={"idempotent": True, "page_id": existing.get("id")})
        return {
            "data": existing,
            "idempotent": True
        }

    # uniqueness constraint for active/archived (already enforced); if a deleted row exists, allow create
    def _new_id(prefix, rows):
        return f"{prefix}_{int(time.time()*1000)}_{len(rows)+1}"

    page_id = _new_id("lsp", pages)
    page_row = {
        "id": page_id,
        "graph_id": graphId,
        "title": title.strip(),
        "title_norm": title_norm,
        "is_journal": bool(isJournal),
        "journal_date": journalDate if isJournal else None,
        "properties": properties,
        "content_plaintext": "",
        "status": status,
        "created_at": now,
        "updated_at": now
    }

    # ingest initial contentMarkdown into blocks (simple: split into non-empty lines as top-level blocks)
    created_blocks = []
    if contentMarkdown:
        # only create blocks when page status is active (if created archived/deleted, keep content but no blocks)
        if status == "active":
            lines = [ln.rstrip() for ln in contentMarkdown.splitlines()]
            # treat blank lines as separators; only create blocks for non-empty trimmed
            order = 0
            for ln in lines:
                if not ln.strip():
                    continue
                bid = _new_id("lsb", blocks)
                b = {
                    "id": bid,
                    "graph_id": graphId,
                    "page_id": page_id,
                    "parent_block_id": None,
                    "order_index": order,
                    "content_markdown": ln,
                    "content_plaintext": ln.strip(),
                    "properties": {},
                    "status": "active",
                    "created_at": now,
                    "updated_at": now
                }
                blocks.append(b)
                created_blocks.append(b)
                order += 1
            page_row["content_plaintext"] = "\n".join([b["content_plaintext"] for b in created_blocks]).strip()
        else:
            page_row["content_plaintext"] = contentMarkdown.strip()

    pages.append(page_row)

    # reference extraction and page_links upsert for created blocks; also ensure stale edges removed (none for new)
    def _extract_refs(md):
        # wikilinks: [[Page]]
        # tags: #tag or #[[Page]]
        # properties: key:: [[Page]] or key:: #tag
        wl = []
        tg = []
        prop = []
        for m in re.finditer(r"\[\[([^\]]+?)\]\]", md or ""):
            target = m.group(1).strip()
            if target:
                wl.append((target, m.group(0)))
        # tags #word
        for m in re.finditer(r"(?<!\w)#([A-Za-z0-9_\-\/]+)", md or ""):
            tg.append((m.group(1).strip(), "#" + m.group(1).strip()))
        # tags #[[Page]]
        for m in re.finditer(r"#\[\[([^\]]+?)\]\]", md or ""):
            tg.append((m.group(1).strip(), "#[[" + m.group(1).strip() + "]]"))
        # properties key:: value (capture links/tags in value)
        for m in re.finditer(r"(?m)^\s*([A-Za-z0-9_\-\/]+)::\s*(.+?)\s*$", md or ""):
            key = m.group(1)
            val = m.group(2)
            # links in value
            for m2 in re.finditer(r"\[\[([^\]]+?)\]\]", val):
                prop.append((m2.group(1).strip(), f"{key}:: {m2.group(0)}"))
            for m2 in re.finditer(r"(?<!\w)#([A-Za-z0-9_\-\/]+)", val):
                prop.append((m2.group(1).strip(), f"{key}:: #{m2.group(1).strip()}"))
        return wl, tg, prop

    # helper: ensure target pages exist (active) for extracted references
    def _ensure_page_for_title(t):
        tn = _norm(t)
        p = next((x for x in pages if x.get("graph_id") == graphId and (x.get("title_norm") or "") == tn and x.get("status") != "deleted"), None)
        if p:
            return p
        # create stub page
        pid = _new_id("lsp", pages)
        stub = {
            "id": pid,
            "graph_id": graphId,
            "title": t.strip() or t,
            "title_norm": tn,
            "is_journal": False,
            "journal_date": None,
            "properties": {},
            "content_plaintext": "",
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        pages.append(stub)
        return stub

    def _upsert_edges_for_block(block_row, source_page_id):
        nonlocal page_links
        # delete stale edges for this block (maintain uniqueness and freshness)
        page_links = [e for e in page_links if not (e.get("graph_id") == graphId and e.get("source_block_id") == block_row.get("id"))]
        wl, tg, prop = _extract_refs(block_row.get("content_markdown") or "")
        new_edges = []
        def _add(kind, title_text, anchor):
            tgt_page = _ensure_page_for_title(title_text)
            new_edges.append({
                "id": _new_id("lspl", page_links),
                "graph_id": graphId,
                "source_page_id": source_page_id,
                "source_block_id": block_row.get("id"),
                "target_page_id": tgt_page.get("id"),
                "link_type": kind,
                "anchor_text": anchor,
                "created_at": now,
                "updated_at": now
            })
        for t, a in wl:
            _add("wikilink", t, a)
        for t, a in tg:
            _add("tag", t, a)
        for t, a in prop:
            _add("property", t, a)

        # enforce uniqueness(graph_id, source_block_id, target_page_id, link_type)
        seen = set()
        for e in new_edges:
            k = (e["graph_id"], e["source_block_id"], e["target_page_id"], e["link_type"])
            if k in seen:
                continue
            seen.add(k)
            page_links.append(e)

    if created_blocks:
        for b in created_blocks:
            _upsert_edges_for_block(b, page_id)
        # content_plaintext already set; updated_at already now

    # Persist
    _save("pages.json", pages)
    _save("blocks.json", blocks)
    _save("page_links.json", page_links)

    _log_call("OK", (time.time() - t0) * 1000, meta={"created": True, "page_id": page_id, "blocks": len(created_blocks)})
    return {"data": page_row, "created_blocks": created_blocks}

def searchPages(graphId, query, status=None, isJournal=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _endpoint = "searchPages"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, credential_id=None, graph_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "rql_" + hashlib.sha1(f"{_endpoint}|{_now()}|{len(logs)}".encode("utf-8")).hexdigest()[:16],
            "endpoint": _endpoint,
            "credential_id": credential_id,
            "graph_id": graph_id,
            "status": status_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(graph_id):
        policies = _load("rate_limits.json")
        if isinstance(policies, list):
            # pick a global/default policy if present
            policy = None
            for p in policies:
                if isinstance(p, dict) and (p.get("scope") in (None, "global", "default")):
                    policy = p
                    break
            if policy:
                window_sec = int(policy.get("window_seconds", 60) or 60)
                max_req = policy.get("max_requests")
                if max_req is not None:
                    try:
                        max_req = int(max_req)
                    except Exception:
                        max_req = None
                if max_req is not None and max_req >= 0:
                    logs = _load("request_logs.json")
                    if not isinstance(logs, list):
                        return None
                    cutoff = time.time() - window_sec
                    cnt = 0
                    for r in logs:
                        if not isinstance(r, dict): 
                            continue
                        if r.get("graph_id") != graph_id:
                            continue
                        ts = r.get("timestamp")
                        if not isinstance(ts, str):
                            continue
                        try:
                            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                            if dt.tzinfo is None:
                                dt = dt.replace(tzinfo=datetime.timezone.utc)
                            if dt.timestamp() >= cutoff:
                                cnt += 1
                        except Exception:
                            continue
                    if cnt >= max_req:
                        return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    # Validate inputs
    if not isinstance(graphId, str) or not re.match(r"^lsg_[0-9A-Za-z]+$", graphId):
        _log("VALIDATION_ERROR", graph_id=graphId if isinstance(graphId, str) else None)
        return _err("VALIDATION_ERROR", "graphId is malformed")
    if not isinstance(query, str) or not query.strip():
        _log("VALIDATION_ERROR", graph_id=graphId)
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted", "archived"):
            _log("VALIDATION_ERROR", graph_id=graphId)
            return _err("VALIDATION_ERROR", "Unsupported status")
    if isJournal is not None and not isinstance(isJournal, bool):
        _log("VALIDATION_ERROR", graph_id=graphId)
        return _err("VALIDATION_ERROR", "isJournal must be a boolean")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        _log("VALIDATION_ERROR", graph_id=graphId)
        return _err("VALIDATION_ERROR", "limit out of range (1–50)")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", graph_id=graphId)
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort is None:
        sort = "relevance"
    if not isinstance(sort, str) or sort not in ("relevance", "updated_at", "created_at", "title"):
        _log("VALIDATION_ERROR", graph_id=graphId)
        return _err("VALIDATION_ERROR", "Unsupported sort")
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log("VALIDATION_ERROR", graph_id=graphId)
        return _err("VALIDATION_ERROR", "Unsupported order")

    graphs = _load("graphs.json")
    if not any(isinstance(g, dict) and g.get("id") == graphId for g in graphs):
        _log("NOT_FOUND", graph_id=graphId)
        return _err("NOT_FOUND", "Graph not found")

    # Business rule: operate against exactly one active graph unless internal default_graph_id configured.
    active = [g for g in graphs if isinstance(g, dict) and g.get("status") == "active"]
    default_cfg = _load("config.json")
    default_graph_id = default_cfg.get("default_graph_id") if isinstance(default_cfg, dict) else None
    if default_graph_id:
        # If provided, allow operation if requested graphId matches default and exists
        if graphId != default_graph_id:
            _log("UNAUTHORIZED", graph_id=graphId)
            return _err("UNAUTHORIZED", "Operation not permitted for this graph")
    else:
        if len(active) != 1 or active[0].get("id") != graphId:
            if len(active) == 0:
                _log("NOT_FOUND", graph_id=graphId)
                return _err("NOT_FOUND", "No active graph")
            _log("CONFLICT", graph_id=graphId)
            return _err("CONFLICT", "Multiple active graphs; default_graph_id not configured")

    rl = _enforce_limits(graphId)
    if rl:
        _log("RATE_LIMIT", graph_id=graphId)
        return rl

    pages = _load("pages.json")
    if not isinstance(pages, list):
        pages = []

    # Filter set
    q = query.strip()
    qn = q.lower()
    tokens = [t for t in re.split(r"\s+", qn) if t]
    def _matches(p):
        if not isinstance(p, dict):
            return False
        if p.get("graph_id") != graphId:
            return False
        if status is None:
            if p.get("status") != "active":
                return False
        else:
            if p.get("status") != status:
                return False
        if isJournal is not None:
            if bool(p.get("is_journal")) != isJournal:
                return False
        hay = (str(p.get("title") or "") + "\n" + str(p.get("content_plaintext") or "")).lower()
        # AND-match tokens
        for t in tokens:
            if t not in hay:
                return False
        return True

    matched = [p for p in pages if _matches(p)]

    # Cursor handling: opaque cursor encodes offset and a simple signature for query+filters
    def _sig():
        base = json.dumps({"g": graphId, "q": qn, "s": status, "j": isJournal, "sort": sort, "order": order}, sort_keys=True)
        return hashlib.sha256(base.encode("utf-8")).hexdigest()[:16]

    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or obj.get("sig") != _sig():
                _log("VALIDATION_ERROR", graph_id=graphId)
                return _err("VALIDATION_ERROR", "Invalid cursor")
            offset = int(obj.get("offset", 0) or 0)
            if offset < 0:
                raise ValueError()
        except Exception:
            _log("VALIDATION_ERROR", graph_id=graphId)
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # Scoring for relevance
    def _relevance(p):
        title = str(p.get("title") or "").lower()
        body = str(p.get("content_plaintext") or "").lower()
        score = 0
        for t in tokens:
            if t in title:
                score += 10
            score += body.count(t)
        # prefer recently updated slightly
        try:
            up = datetime.datetime.fromisoformat(str(p.get("updated_at")).replace("Z", "+00:00"))
            score += up.timestamp() / 1e12
        except Exception:
            pass
        return score

    if sort == "relevance":
        matched.sort(key=_relevance, reverse=True)
    elif sort == "updated_at":
        matched.sort(key=lambda p: str(p.get("updated_at") or ""), reverse=(order == "desc"))
    elif sort == "created_at":
        matched.sort(key=lambda p: str(p.get("created_at") or ""), reverse=(order == "desc"))
    elif sort == "title":
        matched.sort(key=lambda p: str(p.get("title_norm") or p.get("title") or ""), reverse=(order == "desc"))

    total = len(matched)
    page = matched[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = {"sig": _sig(), "offset": next_offset}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    # Return basic page fields
    def _shape(p):
        return {
            "id": p.get("id"),
            "graph_id": p.get("graph_id"),
            "title": p.get("title"),
            "title_norm": p.get("title_norm"),
            "is_journal": bool(p.get("is_journal")),
            "journal_date": p.get("journal_date"),
            "properties": p.get("properties") if isinstance(p.get("properties"), dict) else {},
            "status": p.get("status"),
            "created_at": p.get("created_at"),
            "updated_at": p.get("updated_at"),
        }

    resp = {
        "data": {
            "pages": [_shape(p) for p in page],
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
        }
    }
    _log("OK", graph_id=graphId, meta={"matched": total, "returned": len(page)})
    return resp

def getBacklinks(graphId, targetPageId=None, targetTitle=None, linkType=None, includeBlocks=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getBacklinks"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return None

    def _append_log(status_code, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rql_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "graph_id": graphId,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        usage = _load("usage.json")
        if not isinstance(usage, dict):
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        per_min = usage.get("rate_limit_per_minute")
        quota_total = usage.get("quota_calls_total")
        calls_total = usage.get("calls_total")

        now_dt = datetime.datetime.now(datetime.timezone.utc)
        if isinstance(per_min, int) and per_min > 0:
            cutoff = now_dt - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs[-20000:]:
                if not isinstance(r, dict):
                    continue
                dt = _parse_iso(r.get("timestamp") or r.get("ts"))
                if dt and dt >= cutoff:
                    cnt += 1
            if cnt >= per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(quota_total, int) and quota_total >= 0:
            if not isinstance(calls_total, int):
                calls_total = 0
            if calls_total >= quota_total:
                return _err("QUOTA_EXCEEDED", "Quota exceeded")
        return None

    def _usage_bump(status_code):
        usage = _load("usage.json")
        if isinstance(usage, dict):
            usage["calls_total"] = int(usage.get("calls_total") or 0) + 1
            by_ep = usage.get("calls_by_endpoint")
            if not isinstance(by_ep, dict):
                by_ep = {}
            by_ep[endpoint] = int(by_ep.get(endpoint) or 0) + 1
            usage["calls_by_endpoint"] = by_ep
            if status_code and str(status_code).startswith("2"):
                usage["calls_succeeded"] = int(usage.get("calls_succeeded") or 0) + 1
            else:
                usage["calls_failed"] = int(usage.get("calls_failed") or 0) + 1
            _save("usage.json", usage)

    # Validate
    if not isinstance(graphId, str) or not re.match(r"^lsg_[0-9A-Za-z]+$", graphId):
        err = _err("VALIDATION_ERROR", "graphId is malformed.", field="graphId")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    if (targetPageId is None and targetTitle is None) or (targetPageId is not None and targetTitle is not None):
        err = _err("VALIDATION_ERROR", "Provide exactly one of targetPageId or targetTitle.", field="targetPageId/targetTitle")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    if targetPageId is not None:
        if not isinstance(targetPageId, str):
            err = _err("VALIDATION_ERROR", "targetPageId must be a string.", field="targetPageId")
            _append_log("400", {"error": err["error"]})
            _usage_bump("400")
            return err
        # Relax strict pattern; treat non-matching but id-like values as NOT_FOUND later
        if not re.match(r"^[A-Za-z0-9_:-]{6,}$", targetPageId):
            err = _err("VALIDATION_ERROR", "targetPageId is malformed.", field="targetPageId")
            _append_log("400", {"error": err["error"]})
            _usage_bump("400")
            return err

    if targetTitle is not None and not isinstance(targetTitle, str):
        err = _err("VALIDATION_ERROR", "targetTitle must be a string.", field="targetTitle")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    if linkType is not None:
        if not isinstance(linkType, str) or linkType not in ("wikilink", "tag", "property"):
            err = _err("VALIDATION_ERROR", "linkType is unsupported.", field="linkType")
            _append_log("400", {"error": err["error"]})
            _usage_bump("400")
            return err

    if includeBlocks is not None and not isinstance(includeBlocks, bool):
        err = _err("VALIDATION_ERROR", "includeBlocks must be a boolean.", field="includeBlocks")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    if limit is not None:
        if not isinstance(limit, int):
            err = _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
            _append_log("400", {"error": err["error"]})
            _usage_bump("400")
            return err
        if limit < 1 or limit > 200:
            err = _err("VALIDATION_ERROR", "limit is out of range (1–200).", field="limit")
            _append_log("400", {"error": err["error"]})
            _usage_bump("400")
            return err

    if cursor is not None and not isinstance(cursor, str):
        err = _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    lim_err = _enforce_limits()
    if lim_err:
        _append_log("429", {"error": lim_err["error"]})
        _usage_bump("429")
        return lim_err

    graphs = _load("graphs.json")
    pages = _load("pages.json")
    blocks = _load("blocks.json")
    links = _load("page_links.json")

    graph_row = None
    if isinstance(graphs, list):
        for g in graphs:
            if isinstance(g, dict) and g.get("id") == graphId:
                graph_row = g
                break
    if not graph_row:
        err = _err("NOT_FOUND", "Graph not found.", field="graphId")
        _append_log("404", {"error": err["error"]})
        _usage_bump("404")
        return err

    # Resolve target page (must be active)
    target_page = None
    if isinstance(pages, list):
        if targetPageId is not None:
            for p in pages:
                if isinstance(p, dict) and p.get("id") == targetPageId and p.get("graph_id") == graphId and p.get("status") == "active":
                    target_page = p
                    break
        else:
            tnorm = " ".join(targetTitle.strip().lower().split())
            for p in pages:
                if isinstance(p, dict) and p.get("graph_id") == graphId and p.get("status") == "active" and p.get("title_norm") == tnorm:
                    target_page = p
                    break
    if not target_page:
        # Single target missing => NOT_FOUND
        err = _err("NOT_FOUND", "Target page not found.")
        _append_log("404", {"error": err["error"]})
        _usage_bump("404")
        return err

    # Build quick lookups
    page_by_id = {}
    if isinstance(pages, list):
        for p in pages:
            if isinstance(p, dict) and p.get("graph_id") == graphId:
                page_by_id[p.get("id")] = p
    block_by_id = {}
    if isinstance(blocks, list):
        for b in blocks:
            if isinstance(b, dict) and b.get("graph_id") == graphId:
                block_by_id[b.get("id")] = b

    # Filter links -> backlinks
    rows = []
    if isinstance(links, list):
        for l in links:
            if not isinstance(l, dict):
                continue
            if l.get("graph_id") != graphId:
                continue
            if l.get("target_page_id") != target_page.get("id"):
                continue
            if linkType and l.get("link_type") != linkType:
                continue
            sp = page_by_id.get(l.get("source_page_id"))
            tp = page_by_id.get(l.get("target_page_id"))
            if not sp or not tp:
                continue
            if sp.get("status") != "active" or tp.get("status") != "active":
                continue
            rows.append(l)

    # Group by source_page_id
    grouped = {}
    for l in rows:
        sid = l.get("source_page_id")
        g = grouped.get(sid)
        if not g:
            sp = page_by_id.get(sid) or {}
            g = {
                "source_page": sp,
                "source_page_id": sid,
                "count": 0,
                "link_type_counts": {"wikilink": 0, "tag": 0, "property": 0},
                "source_blocks": []
            }
            grouped[sid] = g
        g["count"] += 1
        lt = l.get("link_type")
        if lt in g["link_type_counts"]:
            g["link_type_counts"][lt] += 1
        if includeBlocks:
            b = block_by_id.get(l.get("source_block_id"))
            if b and b.get("status") == "active":
                g["source_blocks"].append(b)

    items = list(grouped.values())
    # Order by count desc, then source page updated_at desc, then title asc
    def _sort_key(it):
        sp = it.get("source_page") or {}
        upd = _parse_iso(sp.get("updated_at") or "") or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        title = (sp.get("title") or "")
        return (-int(it.get("count") or 0), -int(upd.timestamp()), title.lower())
    items.sort(key=_sort_key)

    # Pagination: cursor is source_page_id
    start = 0
    if cursor:
        for i, it in enumerate(items):
            if it.get("source_page_id") == cursor:
                start = i + 1
                break
    lim = limit if limit is not None else 50
    page_items = items[start:start + lim]
    next_cursor = page_items[-1].get("source_page_id") if page_items and (start + lim) < len(items) else None

    resp = {
        "target_page": target_page,
        "data": page_items,
        "total": len(items),
        "has_more": next_cursor is not None,
        "next_cursor": next_cursor
    }

    _append_log("200", {"target_page_id": target_page.get("id"), "includeBlocks": bool(includeBlocks), "linkType": linkType})
    _usage_bump("200")
    return resp

def addJournalEntry(graphId, journalDate, contentMarkdown, properties=None, parentBlockId=None, orderIndex=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _endpoint = "addJournalEntry"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, graph_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "rql_" + hashlib.sha1(f"{_endpoint}|{_now()}|{len(logs)}".encode("utf-8")).hexdigest()[:16],
            "endpoint": _endpoint,
            "credential_id": None,
            "graph_id": graph_id,
            "status": status_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(graph_id):
        policies = _load("rate_limits.json")
        if isinstance(policies, list):
            policy = None
            for p in policies:
                if isinstance(p, dict) and (p.get("scope") in (None, "global", "default")):
                    policy = p
                    break
            if policy:
                window_sec = int(policy.get("window_seconds", 60) or 60)
                max_req = policy.get("max_requests")
                if max_req is not None:
                    try:
                        max_req = int(max_req)
                    except Exception:
                        max_req = None
                if max_req is not None and max_req >= 0:
                    logs = _load("request_logs.json")
                    if not isinstance(logs, list):
                        return None
                    cutoff = time.time() - window_sec
                    cnt = 0
                    for r in logs:
                        if not isinstance(r, dict): 
                            continue
                        if r.get("graph_id") != graph_id:
                            continue
                        ts = r.get("timestamp")
                        if not isinstance(ts, str):
                            continue
                        try:
                            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                            if dt.tzinfo is None:
                                dt = dt.replace(tzinfo=datetime.timezone.utc)
                            if dt.timestamp() >= cutoff:
                                cnt += 1
                        except Exception:
                            continue
                    if cnt >= max_req:
                        return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    def _gen_id(prefix, rows):
        return f"{prefix}_{hashlib.sha1(f'{prefix}|{_now()}|{len(rows)}'.encode('utf-8')).hexdigest()[:12]}"

    def _plaintext(md):
        s = md
        s = re.sub(r"`{1,3}.*?`{1,3}", " ", s, flags=re.S)
        s = re.sub(r"\[\[([^\]]+)\]\]", r"\1", s)
        s = re.sub(r"#([A-Za-z0-9_\-\/]+)", r"\1", s)
        s = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", s)
        s = re.sub(r"[*_>#-]+", " ", s)
        s = re.sub(r"\s+", " ", s).strip()
        return s

    # Validate inputs
    if not isinstance(graphId, str) or not re.match(r"^lsg_[0-9A-Za-z]+$", graphId):
        _log("VALIDATION_ERROR", graph_id=graphId if isinstance(graphId, str) else None)
        return _err("VALIDATION_ERROR", "graphId is malformed")
    if not isinstance(journalDate, str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", journalDate):
        _log("VALIDATION_ERROR", graph_id=graphId)
        return _err("VALIDATION_ERROR", "journalDate must be YYYY-MM-DD")
    try:
        datetime.date.fromisoformat(journalDate)
    except Exception:
        _log("VALIDATION_ERROR", graph_id=graphId)
        return _err("VALIDATION_ERROR", "journalDate is invalid")
    if not isinstance(contentMarkdown, str) or not contentMarkdown.strip():
        _log("VALIDATION_ERROR", graph_id=graphId)
        return _err("VALIDATION_ERROR", "contentMarkdown must be non-empty")
    if properties is None:
        properties = {}
    if not isinstance(properties, dict):
        _log("VALIDATION_ERROR", graph_id=graphId)
        return _err("VALIDATION_ERROR", "properties must be an object")
    if parentBlockId is not None:
        if not isinstance(parentBlockId, str) or not re.match(r"^lsb_[0-9A-Za-z]+$", parentBlockId):
            _log("VALIDATION_ERROR", graph_id=graphId)
            return _err("VALIDATION_ERROR", "parentBlockId is malformed")
    if orderIndex is not None and (not isinstance(orderIndex, int) or orderIndex < 0):
        _log("VALIDATION_ERROR", graph_id=graphId)
        return _err("VALIDATION_ERROR", "orderIndex must be an integer >= 0")

    graphs = _load("graphs.json")
    graph = None
    for g in graphs:
        if isinstance(g, dict) and g.get("id") == graphId:
            graph = g
            break
    if graph is None:
        _log("NOT_FOUND", graph_id=graphId)
        return _err("NOT_FOUND", "Graph not found")

    active = [g for g in graphs if isinstance(g, dict) and g.get("status") == "active"]
    default_cfg = _load("config.json")
    default_graph_id = default_cfg.get("default_graph_id") if isinstance(default_cfg, dict) else None
    if default_graph_id:
        if graphId != default_graph_id:
            _log("UNAUTHORIZED", graph_id=graphId)
            return _err("UNAUTHORIZED", "Operation not permitted for this graph")
    else:
        if len(active) != 1 or active[0].get("id") != graphId:
            if len(active) == 0:
                _log("NOT_FOUND", graph_id=graphId)
                return _err("NOT_FOUND", "No active graph")
            _log("CONFLICT", graph_id=graphId)
            return _err("CONFLICT", "Multiple active graphs; default_graph_id not configured")

    if graph.get("status") != "active":
        _log("INVALID_TRANSITION", graph_id=graphId)
        return _err("INVALID_TRANSITION", "Graph is not writable")

    rl = _enforce_limits(graphId)
    if rl:
        _log("RATE_LIMIT", graph_id=graphId)
        return rl

    pages = _load("pages.json")
    blocks = _load("blocks.json")
    page_links = _load("page_links.json")
    if not isinstance(pages, list): pages = []
    if not isinstance(blocks, list): blocks = []
    if not isinstance(page_links, list): page_links = []

    # Ensure journal page exists (is_journal=true, journal_date=journalDate)
    journal_page = None
    for p in pages:
        if not isinstance(p, dict):
            continue
        if p.get("graph_id") == graphId and p.get("status") == "active" and p.get("is_journal") is True and p.get("journal_date") == journalDate:
            journal_page = p
            break
    if journal_page is None:
        # create journal page; title convention: journalDate
        title = journalDate
        title_norm = journalDate.strip().lower()
        # uniqueness (graph_id, title_norm) where status != deleted
        for p in pages:
            if isinstance(p, dict) and p.get("graph_id") == graphId and p.get("title_norm") == title_norm and p.get("status") != "deleted":
                _log("CONFLICT", graph_id=graphId)
                return _err("CONFLICT", "Page title already exists", field="title")
        now = _now()
        journal_page = {
            "id": _gen_id("lsp", pages),
            "graph_id": graphId,
            "title": title,
            "title_norm": title_norm,
            "is_journal": True,
            "journal_date": journalDate,
            "properties": {},
            "content_plaintext": "",
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        pages.append(journal_page)

    # Validate parent block if provided
    if parentBlockId is not None:
        parent = None
        for b in blocks:
            if isinstance(b, dict) and b.get("id") == parentBlockId:
                parent = b
                break
        if parent is None or parent.get("graph_id") != graphId or parent.get("status") != "active":
            _log("NOT_FOUND", graph_id=graphId)
            return _err("NOT_FOUND", "parentBlockId not found or not active")
        if parent.get("page_id") != journal_page.get("id"):
            _log("VALIDATION_ERROR", graph_id=graphId)
            return _err("VALIDATION_ERROR", "parentBlockId must belong to the same journal page")

    # Determine order index among active siblings
    siblings = []
    for b in blocks:
        if not isinstance(b, dict):
            continue
        if b.get("graph_id") != graphId or b.get("page_id") != journal_page.get("id"):
            continue
        if b.get("status") != "active":
            continue
        if b.get("parent_block_id") != parentBlockId:
            continue
        siblings.append(b)
    used = {int(b.get("order_index")) for b in siblings if isinstance(b.get("order_index"), int)}
    if orderIndex is None:
        orderIndex = (max(used) + 1) if used else 0
    if orderIndex in used:
        _log("CONFLICT", graph_id=graphId)
        return _err("CONFLICT", "orderIndex collides with an existing sibling", field="orderIndex")

    now = _now()
    new_block = {
        "id": _gen_id("lsb", blocks),
        "graph_id": graphId,
        "page_id": journal_page.get("id"),
        "parent_block_id": parentBlockId,
        "order_index": int(orderIndex),
        "content_markdown": contentMarkdown,
        "content_plaintext": _plaintext(contentMarkdown),
        "properties": properties,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }
    blocks.append(new_block)

    # Re-extract outgoing references from this block; delete stale edges for this block; upsert unique edges
    def _extract_edges(md):
        edges = []
        # wikilinks [[Page]]
        for m in re.finditer(r"\[\[([^\]]+)\]\]", md):
            t = m.group(1).strip()
            if t:
                edges.append(("wikilink", t, m.group(0)))
        # tags #tag
        for m in re.finditer(r"(^|[^\w])#([A-Za-z0-9_\-\/]+)", md):
            t = m.group(2).strip()
            if t:
                edges.append(("tag", t, "#" + t))
        # property-like refs key:: [[Page]]
        for m in re.finditer(r"([A-Za-z0-9_\-]+)::\s*\[\[([^\]]+)\]\]", md):
            t = m.group(2).strip()
            if t:
                edges.append(("property", t, m.group(0)))
        return edges

    def _norm_title(t):
        return re.sub(r"\s+", " ", t.strip().lower())

    # Ensure target pages exist? Rule: derived page_links reference pages.id; do not fabricate pages.
    title_to_page_active = {}
    for p in pages:
        if isinstance(p, dict) and p.get("graph_id") == graphId and p.get("status") == "active":
            title_to_page_active[p.get("title_norm")] = p

    # Delete stale edges for this block in this graph
    page_links = [e for e in page_links if not (isinstance(e, dict) and e.get("graph_id") == graphId and e.get("source_block_id") == new_block["id"])]
    # Upsert edges
    edges = _extract_edges(contentMarkdown)
    existing_keys = set()
    for e in page_links:
        if isinstance(e, dict):
            existing_keys.add((e.get("graph_id"), e.get("source_block_id"), e.get("target_page_id"), e.get("link_type")))
    for lt, tgt_title, anchor in edges:
        tgt = title_to_page_active.get(_norm_title(tgt_title))
        if not tgt:
            continue
        key = (graphId, new_block["id"], tgt.get("id"), lt)
        if key in existing_keys:
            continue
        existing_keys.add(key)
        page_links.append({
            "id": _gen_id("lsl", page_links),  # not specified; keep unique
            "graph_id": graphId,
            "source_page_id": journal_page.get("id"),
            "source_block_id": new_block["id"],
            "target_page_id": tgt.get("id"),
            "link_type": lt,
            "anchor_text": anchor,
            "created_at": now,
            "updated_at": now,
        })

    # Update journal page denormalized content_plaintext and updated_at
    # (simple recompute by concatenating active blocks for the page ordered by (parent_block_id, order_index) not strictly tree; adequate)
    page_blocks = [b for b in blocks if isinstance(b, dict) and b.get("graph_id") == graphId and b.get("page_id") == journal_page["id"] and b.get("status") == "active"]
    page_blocks.sort(key=lambda b: ("" if b.get("parent_block_id") is None else str(b.get("parent_block_id")), int(b.get("order_index") or 0)))
    journal_page["content_plaintext"] = "\n".join([str(b.get("content_plaintext") or "") for b in page_blocks]).strip()
    journal_page["updated_at"] = now

    _save("pages.json", pages)
    _save("blocks.json", blocks)
    _save("page_links.json", page_links)

    resp = {
        "data": {
            "graph_id": graphId,
            "journal_page": {
                "id": journal_page.get("id"),
                "title": journal_page.get("title"),
                "journal_date": journal_page.get("journal_date"),
                "updated_at": journal_page.get("updated_at"),
                "created_at": journal_page.get("created_at"),
            },
            "block": new_block,
        }
    }
    _log("OK", graph_id=graphId, meta={"page_id": journal_page.get("id"), "block_id": new_block.get("id")})
    return resp

def analyzeGraph(graphId, forceRecompute=None, includeDeleted=None, limitPages=None, limitBlocks=None, **_extra):
    import json, os, datetime, re, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _endpoint = "analyzeGraph"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, graph_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "rql_" + hashlib.sha1(f"{_endpoint}|{_now()}|{len(logs)}".encode("utf-8")).hexdigest()[:16],
            "endpoint": _endpoint,
            "credential_id": None,
            "graph_id": graph_id,
            "status": status_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(graph_id):
        policies = _load("rate_limits.json")
        if isinstance(policies, list):
            policy = None
            for p in policies:
                if isinstance(p, dict) and (p.get("scope") in (None, "global", "default")):
                    policy = p
                    break
            if policy:
                window_sec = int(policy.get("window_seconds", 60) or 60)
                max_req = policy.get("max_requests")
                if max_req is not None:
                    try:
                        max_req = int(max_req)
                    except Exception:
                        max_req = None
                if max_req is not None and max_req >= 0:
                    logs = _load("request_logs.json")
                    if not isinstance(logs, list):
                        return None
                    cutoff = time.time() - window_sec
                    cnt = 0
                    for r in logs:
                        if not isinstance(r, dict): 
                            continue
                        if r.get("graph_id") != graph_id:
                            continue
                        ts = r.get("timestamp")
                        if not isinstance(ts, str):
                            continue
                        try:
                            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                            if dt.tzinfo is None:
                                dt = dt.replace(tzinfo=datetime.timezone.utc)
                            if dt.timestamp() >= cutoff:
                                cnt += 1
                        except Exception:
                            continue
                    if cnt >= max_req:
                        return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    def _gen_id(prefix, rows):
        return f"{prefix}_{hashlib.sha1(f'{prefix}|{_now()}|{len(rows)}'.encode('utf-8')).hexdigest()[:12]}"

    # Validate
    if not isinstance(graphId, str) or not re.match(r"^lsg_[0-9A-Za-z]+$", graphId):
        _log("VALIDATION_ERROR", graph_id=graphId if isinstance(graphId, str) else None)
        return _err("VALIDATION_ERROR", "graphId is malformed")
    if forceRecompute is None:
        forceRecompute = False
    if includeDeleted is None:
        includeDeleted = False
    if not isinstance(forceRecompute, bool):
        _log("VALIDATION_ERROR", graph_id=graphId)
        return _err("VALIDATION_ERROR", "forceRecompute must be a boolean")
    if not isinstance(includeDeleted, bool):
        _log("VALIDATION_ERROR", graph_id=graphId)
        return _err("VALIDATION_ERROR", "includeDeleted must be a boolean")
    if limitPages is not None and (not isinstance(limitPages, int) or limitPages < 1):
        _log("VALIDATION_ERROR", graph_id=graphId)
        return _err("VALIDATION_ERROR", "limitPages must be >= 1")
    if limitBlocks is not None and (not isinstance(limitBlocks, int) or limitBlocks < 1):
        _log("VALIDATION_ERROR", graph_id=graphId)
        return _err("VALIDATION_ERROR", "limitBlocks must be >= 1")

    graphs = _load("graphs.json")
    graph = None
    for g in graphs:
        if isinstance(g, dict) and g.get("id") == graphId:
            graph = g
            break
    if graph is None:
        _log("NOT_FOUND", graph_id=graphId)
        return _err("NOT_FOUND", "Graph not found")

    active = [g for g in graphs if isinstance(g, dict) and g.get("status") == "active"]
    default_cfg = _load("config.json")
    default_graph_id = default_cfg.get("default_graph_id") if isinstance(default_cfg, dict) else None
    if default_graph_id:
        if graphId != default_graph_id:
            _log("UNAUTHORIZED", graph_id=graphId)
            return _err("UNAUTHORIZED", "Operation not permitted for this graph")
    else:
        if len(active) != 1 or active[0].get("id") != graphId:
            if len(active) == 0:
                _log("NOT_FOUND", graph_id=graphId)
                return _err("NOT_FOUND", "No active graph")
            _log("CONFLICT", graph_id=graphId)
            return _err("CONFLICT", "Multiple active graphs; default_graph_id not configured")

    rl = _enforce_limits(graphId)
    if rl:
        _log("RATE_LIMIT", graph_id=graphId)
        return rl

    runs = _load("analysis_runs.json")
    if not isinstance(runs, list):
        runs = []
    effective_input = {
        "includeDeleted": includeDeleted,
        "limitPages": limitPages,
        "limitBlocks": limitBlocks,
    }

    # Cache: return recent successful run with same effective inputs if forceRecompute is false
    if not forceRecompute:
        latest = None
        for r in runs:
            if not isinstance(r, dict):
                continue
            if r.get("graph_id") != graphId:
                continue
            if r.get("tool_name") != "analyzeGraph":
                continue
            if r.get("status") != "succeeded":
                continue
            if r.get("input") != effective_input:
                continue
            # recency window: 10 minutes
            try:
                fin = r.get("finished_at")
                dt = datetime.datetime.fromisoformat(str(fin).replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                age = (datetime.datetime.now(datetime.timezone.utc) - dt).total_seconds()
                if age <= 600:
                    if latest is None or str(r.get("finished_at") or "") > str(latest.get("finished_at") or ""):
                        latest = r
            except Exception:
                continue
        if latest is not None:
            resp = {"data": {"run": latest, "result": latest.get("result")}}
            _log("OK", graph_id=graphId, meta={"cache_hit": True, "run_id": latest.get("id")})
            return resp

    # Create a run row queued -> running -> succeeded
    now = _now()
    run = {
        "id": _gen_id("lsr", runs),
        "graph_id": graphId,
        "tool_name": "analyzeGraph",
        "status": "queued",
        "input": effective_input,
        "result": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    runs.append(run)
    _save("analysis_runs.json", runs)

    # Transition to running
    run["status"] = "running"
    run["started_at"] = _now()
    run["updated_at"] = run["started_at"]
    _save("analysis_runs.json", runs)

    pages = _load("pages.json")
    blocks = _load("blocks.json")
    links = _load("page_links.json")
    if not isinstance(pages, list): pages = []
    if not isinstance(blocks, list): blocks = []
    if not isinstance(links, list): links = []

    try:
        # Filter by graph and status
        if includeDeleted:
            pages_g = [p for p in pages if isinstance(p, dict) and p.get("graph_id") == graphId and p.get("status") in ("active", "archived", "deleted")]
            blocks_g = [b for b in blocks if isinstance(b, dict) and b.get("graph_id") == graphId and b.get("status") in ("active", "deleted")]
        else:
            pages_g = [p for p in pages if isinstance(p, dict) and p.get("graph_id") == graphId and p.get("status") == "active"]
            blocks_g = [b for b in blocks if isinstance(b, dict) and b.get("graph_id") == graphId and b.get("status") == "active"]

        # Apply caps
        pages_g.sort(key=lambda p: str(p.get("updated_at") or ""), reverse=True)
        if limitPages is not None:
            pages_g = pages_g[:limitPages]
        page_ids = {p.get("id") for p in pages_g if p.get("id")}

        blocks_g = [b for b in blocks_g if b.get("page_id") in page_ids]
        blocks_g.sort(key=lambda b: str(b.get("updated_at") or ""), reverse=True)
        if limitBlocks is not None:
            blocks_g = blocks_g[:limitBlocks]
        block_ids = {b.get("id") for b in blocks_g if b.get("id")}

        links_g = [e for e in links if isinstance(e, dict) and e.get("graph_id") == graphId]
        # Only count edges whose source/target in selected pages and (if includeDeleted false) pages active
        links_sel = []
        pages_by_id = {p.get("id"): p for p in pages if isinstance(p, dict) and p.get("graph_id") == graphId}
        for e in links_g:
            sp = pages_by_id.get(e.get("source_page_id"))
            tp = pages_by_id.get(e.get("target_page_id"))
            sb = e.get("source_block_id")
            if e.get("source_page_id") not in page_ids or e.get("target_page_id") not in page_ids:
                continue
            if sb and sb not in block_ids:
                continue
            if not includeDeleted:
                if not sp or not tp or sp.get("status") != "active" or tp.get("status") != "active":
                    continue
            links_sel.append(e)

        # Metrics
        page_count = len(pages_g)
        block_count = len(blocks_g)
        link_count = len(links_sel)
        link_density = (link_count / page_count) if page_count else 0.0

        # Centrality: inbound degree
        inbound = {pid: 0 for pid in page_ids}
        outbound = {pid: 0 for pid in page_ids}
        for e in links_sel:
            s = e.get("source_page_id")
            t = e.get("target_page_id")
            if s in outbound: outbound[s] += 1
            if t in inbound: inbound[t] += 1

        def _top(d, n=10):
            items = sorted(d.items(), key=lambda kv: (-kv[1], kv[0] or ""))
            out = []
            for pid, cnt in items[:n]:
                p = pages_by_id.get(pid) or {}
                out.append({"page_id": pid, "title": p.get("title"), "count": int(cnt)})
            return out

        # Basic connected components over page graph (undirected) for selected pages
        adj = {pid: set() for pid in page_ids}
        for e in links_sel:
            s = e.get("source_page_id")
            t = e.get("target_page_id")
            if s in adj and t in adj:
                adj[s].add(t)
                adj[t].add(s)

        seen = set()
        comps = []
        for pid in page_ids:
            if pid in seen:
                continue
            stack = [pid]
            seen.add(pid)
            comp = []
            while stack:
                x = stack.pop()
                comp.append(x)
                for nb in adj.get(x, ()):
                    if nb not in seen:
                        seen.add(nb)
                        stack.append(nb)
            comps.append(comp)
        comps.sort(key=len, reverse=True)

        # Orphans: pages with no in/out links
        orphans = []
        for pid in page_ids:
            if inbound.get(pid, 0) == 0 and outbound.get(pid, 0) == 0:
                p = pages_by_id.get(pid) or {}
                orphans.append({"page_id": pid, "title": p.get("title")})
        orphans = orphans[:50]

        result = {
            "graph_id": graphId,
            "computed_at": _now(),
            "inputs": effective_input,
            "metrics": {
                "page_count": page_count,
                "block_count": block_count,
                "link_count": link_count,
                "link_density": link_density,
                "avg_outbound_links_per_page": (sum(outbound.values()) / page_count) if page_count else 0.0,
                "avg_inbound_links_per_page": (sum(inbound.values()) / page_count) if page_count else 0.0,
                "components_count": len(comps),
                "largest_component_size": len(comps[0]) if comps else 0,
            },
            "top_pages": {
                "by_inbound_links": _top(inbound, 10),
                "by_outbound_links": _top(outbound, 10),
            },
            "orphans": orphans,
        }

        # Transition to succeeded
        run["status"] = "succeeded"
        run["result"] = result
        run["error_message"] = None
        run["finished_at"] = _now()
        run["updated_at"] = run["finished_at"]
        _save("analysis_runs.json", runs)

        resp = {"data": {"run": run, "result": result}}
        _log("OK", graph_id=graphId, meta={"cache_hit": False, "run_id": run.get("id")})
        return resp

    except Exception as e:
        # Expected to avoid raising outward; mark failed with message
        run["status"] = "failed"
        run["error_message"] = str(e)
        run["finished_at"] = _now()
        run["updated_at"] = run["finished_at"]
        _save("analysis_runs.json", runs)
        _log("OK", graph_id=graphId, meta={"run_id": run.get("id"), "failed": True})
        return _err("CONFLICT", "Analysis failed", run_id=run.get("id"), detail=str(e))

def findKnowledgeGaps(graph_id, focus_page_ids=None, status_filter=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, used_graph_id=None, details=None):
        logs = _load("request_logs.json")
        row = {
            "id": "rql_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "findKnowledgeGaps",
            "graph_id": used_graph_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if details is not None:
            row["details"] = details
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(graph_id, str) or not re.match(r"^lsg_[0-9A-Z]+$", graph_id):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "graph_id is malformed.")
    if focus_page_ids is not None:
        if not isinstance(focus_page_ids, list) or any((not isinstance(x, str) or not re.match(r"^lsp_[0-9A-Z]+$", x)) for x in focus_page_ids):
            _log("error", graph_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "focus_page_ids must be an array of page IDs.")
    if status_filter is not None:
        if not isinstance(status_filter, list) or any((not isinstance(x, str) or x not in ("active", "archived")) for x in status_filter):
            _log("error", graph_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "status_filter contains unsupported values.", supported=["active", "archived"])
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", graph_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit out of range (1–200).")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", graph_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    graphs = _load("graphs.json")
    g = next((x for x in graphs if x.get("id") == graph_id), None)
    if not g:
        _log("error", graph_id, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Graph not found.")
    # Business rule: tools operate against exactly one active graph unless internal default configured.
    active_graphs = [x for x in graphs if x.get("status") == "active"]
    default_cfg = _load("config.json")
    default_graph_id = None
    if isinstance(default_cfg, dict):
        default_graph_id = default_cfg.get("default_graph_id")
    if default_graph_id:
        if graph_id != default_graph_id:
            _log("error", graph_id, {"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "Graph is not the configured default graph.")
    else:
        if len(active_graphs) != 1 or active_graphs[0].get("id") != graph_id:
            _log("error", graph_id, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "No single active graph is available for this operation.")

    pages = _load("pages.json")
    page_links = _load("page_links.json")

    allowed_statuses = set(status_filter) if status_filter else {"active"}
    candidate_pages = [p for p in pages if p.get("graph_id") == graph_id and p.get("status") in allowed_statuses]
    pages_by_id = {p.get("id"): p for p in candidate_pages}

    if focus_page_ids:
        missing = [pid for pid in focus_page_ids if pid not in pages_by_id]
        if missing:
            _log("error", graph_id, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "One or more focus pages were not found in the eligible set.", missing_page_ids=missing)
        focus_set = set(focus_page_ids)
    else:
        focus_set = set(pages_by_id.keys())

    inbound = {pid: 0 for pid in focus_set}
    outbound = {pid: 0 for pid in focus_set}
    # count links among eligible pages; inbound counted only if target in focus_set, source eligible
    for e in page_links:
        if e.get("graph_id") != graph_id:
            continue
        sp = e.get("source_page_id")
        tp = e.get("target_page_id")
        if sp in pages_by_id:
            if sp in focus_set:
                outbound[sp] = outbound.get(sp, 0) + 1
            if tp in focus_set:
                inbound[tp] = inbound.get(tp, 0) + 1

    items = []
    for pid in focus_set:
        p = pages_by_id.get(pid)
        if not p:
            continue
        inb = inbound.get(pid, 0)
        outb = outbound.get(pid, 0)
        # simple heuristics: orphan/low-inbound
        if inb == 0:
            severity = "high"
            kind = "orphan"
        elif inb <= 1:
            severity = "medium"
            kind = "low_inbound"
        else:
            severity = "low"
            kind = "ok"
        # only return true gaps (exclude ok)
        if kind == "ok":
            continue
        items.append({
            "page_id": pid,
            "title": p.get("title"),
            "status": p.get("status"),
            "inbound_links": inb,
            "outbound_links": outb,
            "gap_type": kind,
            "severity": severity
        })

    # Sort: highest severity, then lowest inbound, then updated_at desc
    sev_rank = {"high": 0, "medium": 1, "low": 2}
    def _p_updated(p_id):
        p = pages_by_id.get(p_id, {})
        return p.get("updated_at") or ""
    items.sort(key=lambda it: (sev_rank.get(it["severity"], 9), it["inbound_links"], -int(re.sub(r"\D", "", (_p_updated(it["page_id"]) or "0"))[:14] or "0")))

    # Pagination via cursor=base64(json({"offset": n}))
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                offset = obj["offset"]
            else:
                _log("error", graph_id, {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "cursor is invalid.")
        except Exception:
            _log("error", graph_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    total = len(items)
    page_items = items[offset:offset + limit]
    next_cursor = None
    if offset + limit < total:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": offset + limit}).encode("utf-8")).decode("utf-8").rstrip("=")

    # Persist analysis run (succeeded)
    runs = _load("analysis_runs.json")
    run_id = "lsr_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    run = {
        "id": run_id,
        "graph_id": graph_id,
        "tool_name": "findKnowledgeGaps",
        "status": "succeeded",
        "input": {
            "graph_id": graph_id,
            "focus_page_ids": focus_page_ids or None,
            "status_filter": status_filter or None,
            "limit": limit,
            "cursor": cursor
        },
        "result": {
            "items": page_items,
            "total": total,
            "has_more": (offset + limit < total),
            "next_cursor": next_cursor
        },
        "error_message": None,
        "started_at": now,
        "finished_at": now,
        "created_at": now,
        "updated_at": now
    }
    runs.append(run)
    _save("analysis_runs.json", runs)

    _log("ok", graph_id)
    return {
        "run_id": run_id,
        "items": page_items,
        "total": total,
        "has_more": (offset + limit < total),
        "next_cursor": next_cursor
    }

def analyzeJournalPatterns(graph_id, start_date=None, end_date=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64
    from collections import Counter, defaultdict

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, used_graph_id=None, details=None):
        logs = _load("request_logs.json")
        row = {
            "id": "rql_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "analyzeJournalPatterns",
            "graph_id": used_graph_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if details is not None:
            row["details"] = details
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(graph_id, str) or not re.match(r"^lsg_[0-9A-Z]+$", graph_id):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "graph_id is malformed.")
    if start_date is not None and (not isinstance(start_date, str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", start_date)):
        _log("error", graph_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "start_date must be in YYYY-MM-DD.")
    if end_date is not None and (not isinstance(end_date, str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", end_date)):
        _log("error", graph_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "end_date must be in YYYY-MM-DD.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", graph_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit out of range (1–200).")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", graph_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    graphs = _load("graphs.json")
    g = next((x for x in graphs if x.get("id") == graph_id), None)
    if not g:
        _log("error", graph_id, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Graph not found.")
    active_graphs = [x for x in graphs if x.get("status") == "active"]
    default_cfg = _load("config.json")
    default_graph_id = default_cfg.get("default_graph_id") if isinstance(default_cfg, dict) else None
    if default_graph_id:
        if graph_id != default_graph_id:
            _log("error", graph_id, {"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "Graph is not the configured default graph.")
    else:
        if len(active_graphs) != 1 or active_graphs[0].get("id") != graph_id:
            _log("error", graph_id, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "No single active graph is available for this operation.")

    pages = _load("pages.json")
    blocks = _load("blocks.json")
    links = _load("page_links.json")

    # Journal pages in range, active only
    jpages = [p for p in pages if p.get("graph_id") == graph_id and p.get("status") == "active" and p.get("is_journal") is True and isinstance(p.get("journal_date"), str)]
    if start_date:
        jpages = [p for p in jpages if p.get("journal_date") >= start_date]
    if end_date:
        jpages = [p for p in jpages if p.get("journal_date") <= end_date]
    jpages.sort(key=lambda p: p.get("journal_date") or "")

    jpage_ids = {p.get("id") for p in jpages}
    blocks_in = [b for b in blocks if b.get("graph_id") == graph_id and b.get("status") == "active" and b.get("page_id") in jpage_ids]

    # Tags via page_links with link_type='tag' and source_page_id in journal pages
    tag_edges = [e for e in links if e.get("graph_id") == graph_id and e.get("link_type") == "tag" and e.get("source_page_id") in jpage_ids]
    tag_counts = Counter()
    tag_by_date = defaultdict(Counter)
    for e in tag_edges:
        tp = e.get("target_page_id")
        sp = e.get("source_page_id")
        jp = next((p for p in jpages if p.get("id") == sp), None)
        if not jp or not tp:
            continue
        tag_counts[tp] += 1
        tag_by_date[jp["journal_date"]][tp] += 1

    # Streak computation over journal pages that have any active blocks
    blocks_by_page = defaultdict(int)
    for b in blocks_in:
        pid = b.get("page_id")
        if pid:
            blocks_by_page[pid] += 1
    dates_with_content = sorted({p.get("journal_date") for p in jpages if blocks_by_page.get(p.get("id"), 0) > 0 and p.get("journal_date")})
    def _to_date(s):
        return datetime.date(int(s[0:4]), int(s[5:7]), int(s[8:10]))
    streaks = []
    if dates_with_content:
        cur_start = dates_with_content[0]
        prev = dates_with_content[0]
        for d in dates_with_content[1:]:
            if (_to_date(d) - _to_date(prev)).days == 1:
                prev = d
            else:
                streaks.append({"start_date": cur_start, "end_date": prev, "days": (_to_date(prev) - _to_date(cur_start)).days + 1})
                cur_start, prev = d, d
        streaks.append({"start_date": cur_start, "end_date": prev, "days": (_to_date(prev) - _to_date(cur_start)).days + 1})
    longest = max(streaks, key=lambda s: s["days"], default=None)

    # Build findings list (ranked)
    findings = []
    findings.append({
        "type": "summary",
        "journal_pages": len(jpages),
        "journal_pages_with_content": len(dates_with_content),
        "total_blocks": len(blocks_in),
        "longest_streak": longest
    })

    # Top tags (return ids; titles can be joined from pages)
    pages_by_id = {p.get("id"): p for p in pages if p.get("graph_id") == graph_id}
    top_tags = []
    for pid, cnt in tag_counts.most_common(50):
        top_tags.append({"tag_page_id": pid, "tag_title": pages_by_id.get(pid, {}).get("title"), "count": cnt})
    if top_tags:
        findings.append({"type": "top_tags", "items": top_tags})

    # Daily tag peaks (sparse)
    daily_peaks = []
    for d, c in tag_by_date.items():
        if not c:
            continue
        pid, cnt = c.most_common(1)[0]
        daily_peaks.append({"journal_date": d, "top_tag_page_id": pid, "top_tag_title": pages_by_id.get(pid, {}).get("title"), "count": cnt})
    daily_peaks.sort(key=lambda x: x["journal_date"])
    if daily_peaks:
        findings.append({"type": "daily_tag_peaks", "items": daily_peaks})

    # Pagination over findings list (not inner arrays)
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                offset = obj["offset"]
            else:
                _log("error", graph_id, {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "cursor is invalid.")
        except Exception:
            _log("error", graph_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    total = len(findings)
    page_findings = findings[offset:offset + limit]
    next_cursor = None
    if offset + limit < total:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": offset + limit}).encode("utf-8")).decode("utf-8").rstrip("=")

    runs = _load("analysis_runs.json")
    run_id = "lsr_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    run = {
        "id": run_id,
        "graph_id": graph_id,
        "tool_name": "analyzeJournalPatterns",
        "status": "succeeded",
        "input": {
            "graph_id": graph_id,
            "start_date": start_date,
            "end_date": end_date,
            "limit": limit,
            "cursor": cursor
        },
        "result": {
            "findings": page_findings,
            "total": total,
            "has_more": (offset + limit < total),
            "next_cursor": next_cursor
        },
        "error_message": None,
        "started_at": now,
        "finished_at": now,
        "created_at": now,
        "updated_at": now
    }
    runs.append(run)
    _save("analysis_runs.json", runs)

    _log("ok", graph_id)
    return {
        "run_id": run_id,
        "findings": page_findings,
        "total": total,
        "has_more": (offset + limit < total),
        "next_cursor": next_cursor
    }

def smartQuery(graph_id, query, entity_types=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64
    from collections import defaultdict

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, used_graph_id=None, details=None):
        logs = _load("request_logs.json")
        row = {
            "id": "rql_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "smartQuery",
            "graph_id": used_graph_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if details is not None:
            row["details"] = details
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(graph_id, str) or not re.match(r"^lsg_[0-9A-Z]+$", graph_id):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "graph_id is malformed.")
    if not isinstance(query, str) or not query.strip():
        _log("error", graph_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")
    if entity_types is not None:
        if not isinstance(entity_types, list) or any((not isinstance(x, str) or x not in ("pages", "blocks")) for x in entity_types):
            _log("error", graph_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "entity_types contains unsupported values.", supported=["pages", "blocks"])
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", graph_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit out of range (1–200).")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", graph_id, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    graphs = _load("graphs.json")
    g = next((x for x in graphs if x.get("id") == graph_id), None)
    if not g:
        _log("error", graph_id, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Graph not found.")
    active_graphs = [x for x in graphs if x.get("status") == "active"]
    default_cfg = _load("config.json")
    default_graph_id = default_cfg.get("default_graph_id") if isinstance(default_cfg, dict) else None
    if default_graph_id:
        if graph_id != default_graph_id:
            _log("error", graph_id, {"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "Graph is not the configured default graph.")
    else:
        if len(active_graphs) != 1 or active_graphs[0].get("id") != graph_id:
            _log("error", graph_id, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "No single active graph is available for this operation.")

    allowed = set(entity_types) if entity_types else {"pages", "blocks"}

    pages = _load("pages.json")
    blocks = _load("blocks.json")
    links = _load("page_links.json")

    q = query.strip()

    # Very small "smart" parser:
    # - tag:foo or #foo => tag page title match
    # - backlinks:Title => pages linking to that page
    # - otherwise keyword search over titles/content_plaintext
    tag_term = None
    backlinks_term = None
    m = re.search(r"(?:^|\s)backlinks:(.+)$", q, flags=re.I)
    if m:
        backlinks_term = m.group(1).strip()
    mt = re.search(r"(?:^|\s)(?:tag:|#)([^\s]+)", q, flags=re.I)
    if mt:
        tag_term = mt.group(1).strip()

    pages_active = [p for p in pages if p.get("graph_id") == graph_id and p.get("status") == "active"]
    pages_by_id = {p.get("id"): p for p in pages_active}

    results = []

    def _add_page(p, score, reason):
        results.append({
            "entity_type": "pages",
            "page": {
                "id": p.get("id"),
                "title": p.get("title"),
                "is_journal": p.get("is_journal"),
                "journal_date": p.get("journal_date"),
                "updated_at": p.get("updated_at"),
            },
            "score": score,
            "reason": reason
        })

    def _add_block(b, score, reason):
        results.append({
            "entity_type": "blocks",
            "block": {
                "id": b.get("id"),
                "page_id": b.get("page_id"),
                "parent_block_id": b.get("parent_block_id"),
                "order_index": b.get("order_index"),
                "content_markdown": b.get("content_markdown"),
                "updated_at": b.get("updated_at"),
            },
            "score": score,
            "reason": reason
        })

    if backlinks_term:
        # resolve target page by title_norm exact match
        tn = re.sub(r"\s+", " ", backlinks_term.strip().lower())
        target = next((p for p in pages_active if p.get("title_norm") == tn), None)
        if target:
            target_id = target.get("id")
            inbound_sources = defaultdict(int)
            for e in links:
                if e.get("graph_id") != graph_id:
                    continue
                if e.get("target_page_id") != target_id:
                    continue
                sp = e.get("source_page_id")
                if sp in pages_by_id:
                    inbound_sources[sp] += 1
            if "pages" in allowed:
                for sp, cnt in inbound_sources.items():
                    _add_page(pages_by_id[sp], 1000 + cnt, f"backlinks to {target.get('title')}: {cnt}")
        # if target not found => empty result set (not error)

    elif tag_term:
        # find tag page by title_norm
        tn = re.sub(r"\s+", " ", tag_term.strip().lower())
        tag_page = next((p for p in pages_active if p.get("title_norm") == tn), None)
        if tag_page:
            tag_id = tag_page.get("id")
            src_pages = set()
            src_blocks = set()
            for e in links:
                if e.get("graph_id") != graph_id or e.get("link_type") != "tag":
                    continue
                if e.get("target_page_id") != tag_id:
                    continue
                sp = e.get("source_page_id")
                sb = e.get("source_block_id")
                if sp in pages_by_id:
                    src_pages.add(sp)
                if sb:
                    src_blocks.add(sb)
            if "pages" in allowed:
                for pid in src_pages:
                    _add_page(pages_by_id[pid], 900, f"tagged with {tag_page.get('title')}")
            if "blocks" in allowed:
                for b in blocks:
                    if b.get("graph_id") == graph_id and b.get("status") == "active" and b.get("id") in src_blocks:
                        _add_block(b, 800, f"tagged with {tag_page.get('title')}")
        # if tag page not found => empty set

    else:
        # keyword search
        terms = [t for t in re.split(r"\s+", q.lower()) if t]
        if "pages" in allowed:
            for p in pages_active:
                hay = (p.get("title") or "").lower() + "\n" + (p.get("content_plaintext") or "").lower()
                score = 0
                for t in terms:
                    if t in (p.get("title") or "").lower():
                        score += 10
                    if t in hay:
                        score += 1
                if score > 0:
                    _add_page(p, score, "keyword match")
        if "blocks" in allowed:
            for b in blocks:
                if b.get("graph_id") != graph_id or b.get("status") != "active":
                    continue
                # only blocks whose page is active
                if b.get("page_id") not in pages_by_id:
                    continue
                hay = ((b.get("content_plaintext") or "") + "\n" + (b.get("content_markdown") or "")).lower()
                score = 0
                for t in terms:
                    if t in hay:
                        score += 1
                if score > 0:
                    _add_block(b, score, "keyword match")

    # Sort by score desc, then updated_at desc if present
    def _updated_key(r):
        if r["entity_type"] == "pages":
            return r["page"].get("updated_at") or ""
        return r["block"].get("updated_at") or ""
    results.sort(key=lambda r: (-(r.get("score") or 0), _updated_key(r)), reverse=False)

    # Pagination
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                offset = obj["offset"]
            else:
                _log("error", graph_id, {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "cursor is invalid.")
        except Exception:
            _log("error", graph_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    total = len(results)
    page_results = results[offset:offset + limit]
    next_cursor = None
    if offset + limit < total:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": offset + limit}).encode("utf-8")).decode("utf-8").rstrip("=")

    runs = _load("analysis_runs.json")
    run_id = "lsr_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    run = {
        "id": run_id,
        "graph_id": graph_id,
        "tool_name": "smartQuery",
        "status": "succeeded",
        "input": {
            "graph_id": graph_id,
            "query": query,
            "entity_types": entity_types or None,
            "limit": limit,
            "cursor": cursor
        },
        "result": {
            "results": page_results,
            "total": total,
            "has_more": (offset + limit < total),
            "next_cursor": next_cursor
        },
        "error_message": None,
        "started_at": now,
        "finished_at": now,
        "created_at": now,
        "updated_at": now
    }
    runs.append(run)
    _save("analysis_runs.json", runs)

    _log("ok", graph_id)
    return {
        "run_id": run_id,
        "results": page_results,
        "total": total,
        "has_more": (offset + limit < total),
        "next_cursor": next_cursor
    }

