        if source_page_id not in pages_by_id:
            _log("error", graph_id, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Source page not found or not active.")
        scoped_page_id = source_page_id

    # Build adjacency among active pages (ignore links from/to non-active pages)
    out_neighbors = defaultdict(set)
    in_neighbors = defaultdict(set)
    for e in links:
        if e.get("graph_id") != graph_id:
            continue
        sp = e.get("source_page_id")
        tp = e.get("target_page_id")
        if sp in pages_by_id and tp in pages_by_id:
            out_neighbors[sp].add(tp)
            in_neighbors[tp].add(sp)

    # Co-occurrence / shared neighbors suggestion:
    # for each candidate pair (A -> C) where C is neighbor-of-neighbor but not directly linked, score by shared neighbors
    suggestions = []

    def _suggest_from(source_pid):
        existing = out_neighbors.get(source_pid, set())
        # candidates via two-hop (out then out) and shared inbound neighbors
        cand_scores = defaultdict(int)

        # shared outgoing neighbors-of-neighbors
        for mid in out_neighbors.get(source_pid, set()):
            for cand in out_neighbors.get(mid, set()):
                if cand == source_pid or cand in existing:
                    continue
                cand_scores[cand] += 3

        # shared inbound (common pages that link to both)
        for other in pages_by_id.keys():
            if other == source_pid or other in existing:
                continue
            shared = len(in_neighbors.get(source_pid, set()) & in_neighbors.get(other, set()))
            if shared:
                cand_scores[other] += shared

        # shared outgoing (common pages both link to)
        for other in pages_by_id.keys():
            if other == source_pid or other in existing:
                continue
            shared = len(out_neighbors.get(source_pid, set()) & out_neighbors.get(other, set()))
            if shared:
                cand_scores[other] += shared

        for cand, score in cand_scores.items():
            if score <= 0:
                continue
            suggestions.append({
                "source_page_id": source_pid,
                "source_title": pages_by_id.get(source_pid, {}).get("title"),
                "target_page_id": cand,
                "target_title": pages_by_id.get(cand, {}).get("title"),
                "score": score,
                "reason": "shared neighbors / co-occurrence"
            })

    if scoped_page_id:
        _suggest_from(scoped_page_id)
    else:
        # global: pick top sources by degree for manageable suggestions
        deg = []
        for pid in pages_by_id.keys():
            deg.append((-(len(out_neighbors.get(pid, set())) + len(in_neighbors.get(pid, set()))), pid))
        deg.sort()
        for _, pid in deg[:50]:
            _suggest_from(pid)

    # Deduplicate by (source,target) keep max score
    best = {}
    for s in suggestions:
        k = (s["source_page_id"], s["target_page_id"])
        if k not in best or s["score"] > best[k]["score"]:
            best[k] = s
    suggestions = list(best.values())
    suggestions.sort(key=lambda s: (-s.get("score", 0), s.get("source_title") or "", s.get("target_title") or ""))

    # Pagination
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                offset = obj["offset"]
            else:
                _log("error", graph_id, {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "cursor is invalid.")
        except Exception:
            _log("error", graph_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    total = len(suggestions)
    page_suggestions = suggestions[offset:offset + limit]
    next_cursor = None
    if offset + limit < total:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": offset + limit}).encode("utf-8")).decode("utf-8").rstrip("=")

    # Persist analysis run (suggestions not written to page_links)
    runs = _load("analysis_runs.json")
    run_id = "lsr_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    run = {
        "id": run_id,
        "graph_id": graph_id,
        "tool_name": "suggestConnections",
        "status": "succeeded",
        "input": {
            "graph_id": graph_id,
            "source_page_id": source_page_id,
            "source_block_id": source_block_id,
            "limit": limit,
            "cursor": cursor
        },
        "result": {
            "suggestions": page_suggestions,
            "total": total,
            "has_more": (offset + limit < total),
            "next_cursor": next_cursor
        },
        "error_message": None,
        "started_at": now,
        "finished_at": now,
        "created_at": now,
        "updated_at": now
    }
    runs.append(run)
    _save("analysis_runs.json", runs)

    _log("ok", graph_id)
    return {
        "run_id": run_id,
        "suggestions": page_suggestions,
        "total": total,
        "has_more": (offset + limit < total),
        "next_cursor": next_cursor
    }

def addJournalBlock(graph_id, journal_date, content_markdown, parent_block_id=None, order_index=None, properties=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    reqlog_name = "request_logs.json"
    usage_name = "usage.json"

    def _log(status, endpoint, detail=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load(reqlog_name)
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "rql_" + uuid.uuid4().hex[:16],
            "endpoint": endpoint,
            "status": status,
            "detail": detail,
            "latency_ms": latency_ms,
            "timestamp": now
        })
        _save(reqlog_name, logs)

        usage = _load(usage_name)
        if not isinstance(usage, dict): usage = {}
        usage.setdefault("calls_total", 0)
        usage["calls_total"] += 1
        usage.setdefault("calls_by_endpoint", {})
        usage["calls_by_endpoint"].setdefault(endpoint, 0)
        usage["calls_by_endpoint"][endpoint] += 1

        # very small default rate limit window if present in store
        rl = usage.get("rate_limit_per_minute")
        if isinstance(rl, int) and rl > 0:
            cutoff = (datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)).isoformat()
            recent = [r for r in logs if isinstance(r, dict) and r.get("timestamp", "") >= cutoff]
            if len(recent) > rl:
                usage.setdefault("rate_limited_total", 0)
                usage["rate_limited_total"] += 1
                _save(usage_name, usage)
                return _err("RATE_LIMIT", "Rate limit exceeded")
        quota = usage.get("quota_calls_total")
        if isinstance(quota, int) and quota >= 0 and usage["calls_total"] > quota:
            usage.setdefault("quota_exceeded_total", 0)
            usage["quota_exceeded_total"] += 1
            _save(usage_name, usage)
            return _err("QUOTA_EXCEEDED", "Quota exceeded")
        _save(usage_name, usage)
        return None

    def _validate():
        if not isinstance(graph_id, str) or not re.match(r"^lsg_[0-9A-Z]+$", graph_id):
            return _err("VALIDATION_ERROR", "graph_id is malformed", field="graph_id")
        if not isinstance(journal_date, str) or not journal_date.strip():
            return _err("VALIDATION_ERROR", "journal_date is required", field="journal_date")
        if not re.match(r"^\d{4}-\d{2}-\d{2}$", journal_date.strip()):
            return _err("VALIDATION_ERROR", "journal_date must match YYYY-MM-DD", field="journal_date")
        if not isinstance(content_markdown, str) or content_markdown == "":
            return _err("VALIDATION_ERROR", "content_markdown is required", field="content_markdown")
        if parent_block_id is not None:
            if not isinstance(parent_block_id, str) or not re.match(r"^lsb_[0-9A-Z]+$", parent_block_id):
                return _err("VALIDATION_ERROR", "parent_block_id is malformed", field="parent_block_id")
        if order_index is not None:
            if not isinstance(order_index, int) or order_index < 0:
                return _err("VALIDATION_ERROR", "order_index must be an integer >= 0", field="order_index")
        if properties is not None and not isinstance(properties, dict):
            return _err("VALIDATION_ERROR", "properties must be an object", field="properties")
        return None

    endpoint = "addJournalBlock"
    v = _validate()
    if v:
        _log("error", endpoint, v["error"]["code"])
        return v

    graphs = _load("graphs.json")
    if not isinstance(graphs, list): graphs = []
    graph = next((g for g in graphs if isinstance(g, dict) and g.get("id") == graph_id), None)
    if not graph:
        _log("error", endpoint, "NOT_FOUND")
        return _err("NOT_FOUND", "Graph not found", graph_id=graph_id)

    # Business rule: tools operate against exactly one active graph (server-selected). If mismatch, unauthorized.
    active_graphs = [g for g in graphs if isinstance(g, dict) and g.get("status") == "active"]
    if len(active_graphs) != 1 or active_graphs[0].get("id") != graph_id:
        # If none or multiple active graphs, cannot resolve context
        if len(active_graphs) != 1:
            _log("error", endpoint, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No single active graph context available")
        _log("error", endpoint, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You don’t have access to this graph in the active context", graph_id=graph_id)

    if graph.get("status") != "active":
        _log("error", endpoint, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Graph is not active", status=graph.get("status"))

    pages = _load("pages.json")
    if not isinstance(pages, list): pages = []
    blocks = _load("blocks.json")
    if not isinstance(blocks, list): blocks = []
    page_links = _load("page_links.json")
    if not isinstance(page_links, list): page_links = []

    # ensure journal page exists
    jp = next((p for p in pages if isinstance(p, dict) and p.get("graph_id") == graph_id and p.get("is_journal") is True and p.get("journal_date") == journal_date and p.get("status") == "active"), None)
    if not jp:
        # uniqueness within graph by title_norm; we'll generate a standard title
        title = journal_date
        title_norm = title.strip().lower()
        # if a non-deleted page exists with this title_norm, return conflict (since it's not idempotent by spec here)
        existing_same = next((p for p in pages if isinstance(p, dict) and p.get("graph_id") == graph_id and p.get("title_norm") == title_norm and p.get("status") != "deleted"), None)
        if existing_same:
            _log("error", endpoint, "CONFLICT")
            return _err("CONFLICT", "A page with this title already exists", page_id=existing_same.get("id"))

        pid = "lsp_" + uuid.uuid4().hex[:12].upper()
        jp = {
            "id": pid,
            "graph_id": graph_id,
            "title": title,
            "title_norm": title_norm,
            "is_journal": True,
            "journal_date": journal_date,
            "properties": {},
            "content_plaintext": "",
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        pages.append(jp)
        _save("pages.json", pages)

    # parent block validation
    if parent_block_id is not None:
        parent = next((b for b in blocks if isinstance(b, dict) and b.get("id") == parent_block_id), None)
        if not parent:
            _log("error", endpoint, "NOT_FOUND")
            return _err("NOT_FOUND", "Parent block not found", parent_block_id=parent_block_id)
        if parent.get("graph_id") != graph_id or parent.get("page_id") != jp.get("id"):
            _log("error", endpoint, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_block_id must belong to the same journal page in the graph", parent_block_id=parent_block_id)
        if parent.get("status") != "active":
            _log("error", endpoint, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Parent block is not active", parent_block_id=parent_block_id)

    # determine order_index
    siblings = [b for b in blocks if isinstance(b, dict)
                and b.get("page_id") == jp.get("id")
                and b.get("graph_id") == graph_id
                and b.get("status") == "active"
                and b.get("parent_block_id") == parent_block_id]
    used = {b.get("order_index") for b in siblings if isinstance(b.get("order_index"), int)}
    if order_index is None:
        order_index = 0 if not used else (max(used) + 1)
    else:
        if order_index in used:
            _log("error", endpoint, "CONFLICT")
            return _err("CONFLICT", "order_index collides with an existing active sibling block", order_index=order_index)

    # create block
    bid = "lsb_" + uuid.uuid4().hex[:12].upper()
    bprops = properties if isinstance(properties, dict) else {}
    content_plaintext = re.sub(r"\s+", " ", re.sub(r"[\[\]#*_`>]+", " ", content_markdown)).strip()

    new_block = {
        "id": bid,
        "graph_id": graph_id,
        "page_id": jp.get("id"),
        "parent_block_id": parent_block_id,
        "order_index": int(order_index),
        "content_markdown": content_markdown,
        "content_plaintext": content_plaintext,
        "properties": bprops,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }
    blocks.append(new_block)

    # re-extract outgoing links for this block and upsert page_links; delete stale edges for this block
    def _norm_title(t):
        return " ".join(t.strip().lower().split())

    # delete stale edges for this block in this graph
    page_links = [e for e in page_links if not (isinstance(e, dict) and e.get("graph_id") == graph_id and e.get("source_block_id") == bid)]

    # extract: [[Page]], #tag, and property:: Value (as property link to Page if value looks like [[Page]] or bareword)
    src_page_id = jp.get("id")
    outgoing = []
    for m in re.finditer(r"\[\[([^\]]+)\]\]", content_markdown):
        tgt_title = m.group(1).strip()
        if tgt_title:
            outgoing.append(("wikilink", tgt_title, m.group(0)))
    for m in re.finditer(r"(^|[\s(])#([A-Za-z0-9_\-\/]+)", content_markdown):
        tag = m.group(2).strip()
        if tag:
            outgoing.append(("tag", tag, "#" + tag))
    for m in re.finditer(r"(^|\s)([A-Za-z0-9_\-]+)::\s*([^\n]+)", content_markdown):
        val = m.group(3).strip()
        if val.startswith("[[") and val.endswith("]]"):
            tgt_title = val[2:-2].strip()
            if tgt_title:
                outgoing.append(("property", tgt_title, val))

    # ensure target pages exist? Logseq often allows links to non-existent pages; here we create missing pages as active notes.
    def _get_or_create_page(title):
        tn = _norm_title(title)
        p = next((p for p in pages if isinstance(p, dict) and p.get("graph_id") == graph_id and p.get("title_norm") == tn and p.get("status") == "active"), None)
        if p: return p
        # if archived exists, still allow linking; choose archived as target if active missing
        p2 = next((p for p in pages if isinstance(p, dict) and p.get("graph_id") == graph_id and p.get("title_norm") == tn and p.get("status") in ("archived",)), None)
        if p2: return p2
        # if deleted exists, create a new active row (since deleted is terminal)
        pid = "lsp_" + uuid.uuid4().hex[:12].upper()
        pnew = {
            "id": pid,
            "graph_id": graph_id,
            "title": title.strip(),
            "title_norm": tn,
            "is_journal": False,
            "journal_date": None,
            "properties": {},
            "content_plaintext": "",
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        pages.append(pnew)
        return pnew

    def _upsert_edge(target_page_id, link_type, anchor_text):
        # uniqueness(graph_id, source_block_id, target_page_id, link_type)
        for e in page_links:
            if not isinstance(e, dict): 
                continue
            if e.get("graph_id") == graph_id and e.get("source_block_id") == bid and e.get("target_page_id") == target_page_id and e.get("link_type") == link_type:
                e["updated_at"] = now
                e["anchor_text"] = anchor_text
                e["source_page_id"] = src_page_id
                return
        page_links.append({
            "id": "lsl_" + uuid.uuid4().hex[:12].upper(),
            "graph_id": graph_id,
            "source_page_id": src_page_id,
            "source_block_id": bid,
            "target_page_id": target_page_id,
            "link_type": link_type,
            "anchor_text": anchor_text,
            "created_at": now,
            "updated_at": now
        })

    for link_type, tgt_title, anchor in outgoing:
        tgt_page = _get_or_create_page(tgt_title)
        _upsert_edge(tgt_page.get("id"), link_type, anchor)

    # update page content_plaintext + updated_at
    jp["content_plaintext"] = (jp.get("content_plaintext") or "").strip()
    if jp["content_plaintext"]:
        jp["content_plaintext"] += "\n" + content_plaintext
    else:
        jp["content_plaintext"] = content_plaintext
    jp["updated_at"] = now

    _save("blocks.json", blocks)
    _save("pages.json", pages)
    _save("page_links.json", page_links)

    rlerr = _log("ok", endpoint, None)
    if rlerr:
        return rlerr

    return {"block": new_block}

