def addNoteContent(graph_id, title, content_plaintext, properties=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    reqlog_name = "request_logs.json"
    usage_name = "usage.json"

    def _log(status, endpoint, detail=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load(reqlog_name)
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "rql_" + uuid.uuid4().hex[:16],
            "endpoint": endpoint,
            "status": status,
            "detail": detail,
            "latency_ms": latency_ms,
            "timestamp": now
        })
        _save(reqlog_name, logs)

        usage = _load(usage_name)
        if not isinstance(usage, dict): usage = {}
        usage.setdefault("calls_total", 0)
        usage["calls_total"] += 1
        usage.setdefault("calls_by_endpoint", {})
        usage["calls_by_endpoint"].setdefault(endpoint, 0)
        usage["calls_by_endpoint"][endpoint] += 1

        rl = usage.get("rate_limit_per_minute")
        if isinstance(rl, int) and rl > 0:
            cutoff = (datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)).isoformat()
            recent = [r for r in logs if isinstance(r, dict) and r.get("timestamp", "") >= cutoff]
            if len(recent) > rl:
                usage.setdefault("rate_limited_total", 0)
                usage["rate_limited_total"] += 1
                _save(usage_name, usage)
                return _err("RATE_LIMIT", "Rate limit exceeded")
        quota = usage.get("quota_calls_total")
        if isinstance(quota, int) and quota >= 0 and usage["calls_total"] > quota:
            usage.setdefault("quota_exceeded_total", 0)
            usage["quota_exceeded_total"] += 1
            _save(usage_name, usage)
            return _err("QUOTA_EXCEEDED", "Quota exceeded")
        _save(usage_name, usage)
        return None

    endpoint = "addNoteContent"

    if not isinstance(graph_id, str) or not re.match(r"^lsg_[0-9A-Z]+$", graph_id):
        _log("error", endpoint, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "graph_id is malformed", field="graph_id")
    if not isinstance(title, str) or title.strip() == "":
        _log("error", endpoint, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title is required", field="title")
    if not isinstance(content_plaintext, str) or content_plaintext.strip() == "":
        _log("error", endpoint, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "content_plaintext is required", field="content_plaintext")
    if properties is not None and not isinstance(properties, dict):
        _log("error", endpoint, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "properties must be an object", field="properties")

    graphs = _load("graphs.json")
    if not isinstance(graphs, list): graphs = []
    graph = next((g for g in graphs if isinstance(g, dict) and g.get("id") == graph_id), None)
    if not graph:
        _log("error", endpoint, "NOT_FOUND")
        return _err("NOT_FOUND", "Graph not found", graph_id=graph_id)

    active_graphs = [g for g in graphs if isinstance(g, dict) and g.get("status") == "active"]
    if len(active_graphs) != 1 or active_graphs[0].get("id") != graph_id:
        if len(active_graphs) != 1:
            _log("error", endpoint, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No single active graph context available")
        _log("error", endpoint, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You don’t have access to this graph in the active context", graph_id=graph_id)
    if graph.get("status") != "active":
        _log("error", endpoint, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Graph is not active", status=graph.get("status"))

    pages = _load("pages.json")
    if not isinstance(pages, list): pages = []

    title_clean = title.strip()
    title_norm = " ".join(title_clean.lower().split())

    existing_active = next((p for p in pages if isinstance(p, dict) and p.get("graph_id") == graph_id and p.get("title_norm") == title_norm and p.get("status") == "active"), None)
    if existing_active:
        page = existing_active
        if page.get("is_journal") is True:
            _log("error", endpoint, "CONFLICT")
            return _err("CONFLICT", "A journal page already uses this title", page_id=page.get("id"))
    else:
        # if non-deleted exists (archived), update it by re-activating? not allowed by tool; keep archived and create conflict.
        existing_non_deleted = next((p for p in pages if isinstance(p, dict) and p.get("graph_id") == graph_id and p.get("title_norm") == title_norm and p.get("status") != "deleted"), None)
        if existing_non_deleted and existing_non_deleted.get("status") != "active":
            _log("error", endpoint, "CONFLICT")
            return _err("CONFLICT", "A non-deleted page with this title already exists", page_id=existing_non_deleted.get("id"), status=existing_non_deleted.get("status"))

        pid = "lsp_" + uuid.uuid4().hex[:12].upper()
        page = {
            "id": pid,
            "graph_id": graph_id,
            "title": title_clean,
            "title_norm": title_norm,
            "is_journal": False,
            "journal_date": None,
            "properties": {},
            "content_plaintext": "",
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        pages.append(page)

    if isinstance(properties, dict):
        page["properties"] = properties

    existing = (page.get("content_plaintext") or "")
    newtxt = content_plaintext.strip()
    page["content_plaintext"] = (existing + ("\n" if existing.strip() else "") + newtxt).strip()
    page["updated_at"] = now

    _save("pages.json", pages)

    rlerr = _log("ok", endpoint, None)
    if rlerr:
        return rlerr

    return {"page": page}

def getBlock(block_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getBlock"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return None

    def _append_log(status_code, graph_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rql_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "graph_id": graph_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        usage = _load("usage.json")
        if not isinstance(usage, dict):
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        per_min = usage.get("rate_limit_per_minute")
        quota_total = usage.get("quota_calls_total")
        calls_total = usage.get("calls_total")

        now_dt = datetime.datetime.now(datetime.timezone.utc)
        if isinstance(per_min, int) and per_min > 0:
            cutoff = now_dt - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs[-20000:]:
                if not isinstance(r, dict):
                    continue
                dt = _parse_iso(r.get("timestamp") or r.get("ts"))
                if dt and dt >= cutoff:
                    cnt += 1
            if cnt >= per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(quota_total, int) and quota_total >= 0:
            if not isinstance(calls_total, int):
                calls_total = 0
            if calls_total >= quota_total:
                return _err("QUOTA_EXCEEDED", "Quota exceeded")
        return None

    def _usage_bump(status_code):
        usage = _load("usage.json")
        if isinstance(usage, dict):
            usage["calls_total"] = int(usage.get("calls_total") or 0) + 1
            by_ep = usage.get("calls_by_endpoint")
            if not isinstance(by_ep, dict):
                by_ep = {}
            by_ep[endpoint] = int(by_ep.get(endpoint) or 0) + 1
            usage["calls_by_endpoint"] = by_ep
            if status_code and str(status_code).startswith("2"):
                usage["calls_succeeded"] = int(usage.get("calls_succeeded") or 0) + 1
            else:
                usage["calls_failed"] = int(usage.get("calls_failed") or 0) + 1
            _save("usage.json", usage)

    if not isinstance(block_id, str):
        err = _err("VALIDATION_ERROR", "block_id must be a string.", field="block_id")
        _append_log("400", None, {"error": err["error"]})
        _usage_bump("400")
        return err

    # Relax malformed checks: accept common id-like strings, only reject truly invalid
    if not re.match(r"^[A-Za-z0-9_:-]{6,}$", block_id):
        err = _err("VALIDATION_ERROR", "block_id is malformed.", field="block_id")
        _append_log("400", None, {"error": err["error"]})
        _usage_bump("400")
        return err

    lim_err = _enforce_limits()
    if lim_err:
        _append_log("429", None, {"error": lim_err["error"]})
        _usage_bump("429")
        return lim_err

    blocks = _load("blocks.json")
    pages = _load("pages.json")
    graphs = _load("graphs.json")

    block_row = None
    if isinstance(blocks, list):
        for b in blocks:
            if isinstance(b, dict) and b.get("id") == block_id:
                block_row = b
                break

    if not block_row or block_row.get("status") != "active":
        err = _err("NOT_FOUND", "Block not found.")
        _append_log("404", None, {"error": err["error"]})
        _usage_bump("404")
        return err

    graph_id = block_row.get("graph_id")
    # Access is ambient; authorize if its graph exists
    graph_row = None
    if isinstance(graphs, list):
        for g in graphs:
            if isinstance(g, dict) and g.get("id") == graph_id:
                graph_row = g
                break
    if not graph_row:
        err = _err("UNAUTHORIZED", "You don’t have access to this block’s graph.")
        _append_log("401", graph_id, {"error": err["error"]})
        _usage_bump("401")
        return err

    # Verify owning page belongs to same graph
    page_ok = False
    if isinstance(pages, list):
        for p in pages:
            if isinstance(p, dict) and p.get("id") == block_row.get("page_id") and p.get("graph_id") == graph_id:
                page_ok = True
                break
    if not page_ok:
        err = _err("NOT_FOUND", "Owning page not found for block.")
        _append_log("404", graph_id, {"error": err["error"]})
        _usage_bump("404")
        return err

    resp = {"block": block_row}
    _append_log("200", graph_id, {"block_id": block_id})
    _usage_bump("200")
    return resp

def getAllBlocks(graphId, pageId=None, parentBlockId=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getAllBlocks"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    request_logs = _load("request_logs.json")

    def _log(status_code, credential_id=None, extra=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"rql_{int(time.time()*1000)}",
            "ts": now,
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": latency_ms,
            "credential_id": credential_id
        }
        if extra:
            row.update(extra)
        request_logs.append(row)
        _save("request_logs.json", request_logs)

    # Ambient auth: find a single active graph; must match graphId and be the only active.
    graphs = _load("graphs.json")
    if not isinstance(graphId, str) or not re.match(r"^lsg_[0-9A-Za-z]+$", graphId):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "graphId is malformed.")
    active_graphs = [g for g in graphs if g.get("status") == "active"]
    if len(active_graphs) != 1:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No unique active graph is available for this operation.")
    active_graph = active_graphs[0]
    if active_graph.get("id") != graphId:
        # graph must exist and be accessible; since we only operate on the single active graph, treat mismatch as not found
        if any(g.get("id") == graphId for g in graphs):
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Graph is not available for this operation.")
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Graph not found.")

    if pageId is not None:
        if not isinstance(pageId, str) or not re.match(r"^lsp_[0-9A-Za-z]+$", pageId):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "pageId is malformed.")
    if parentBlockId is not None:
        if not isinstance(parentBlockId, str) or not re.match(r"^lsb_[0-9A-Za-z]+$", parentBlockId):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parentBlockId is malformed.")
    if status is not None:
        if status not in ("active", "deleted"):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported status filter.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer in range 1–500.")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort is None:
        sort = "updated_at"
    if sort not in ("created_at", "updated_at", "order_index"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported sort field.")
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported sort order.")

    pages = _load("pages.json")
    blocks = _load("blocks.json")

    # Validate referenced IDs exist (filters only), per description.
    if pageId is not None:
        if not any(p.get("id") == pageId and p.get("graph_id") == graphId for p in pages):
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Page not found.")
    if parentBlockId is not None:
        pb = next((b for b in blocks if b.get("id") == parentBlockId and b.get("graph_id") == graphId), None)
        if pb is None:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Parent block not found.")

    def _parse_cursor(c):
        # Cursor format: "v1:<offset>"
        if not c:
            return 0
        m = re.match(r"^v1:(\d+)$", c)
        if not m:
            return None
        return int(m.group(1))

    offset = _parse_cursor(cursor)
    if offset is None:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    # Filter
    rows = [b for b in blocks if b.get("graph_id") == graphId]
    if pageId is not None:
        rows = [b for b in rows if b.get("page_id") == pageId]
    if parentBlockId is not None:
        rows = [b for b in rows if b.get("parent_block_id") == parentBlockId]
    if status is not None:
        rows = [b for b in rows if b.get("status") == status]

    # Sort
    reverse = (order == "desc")
    if sort in ("created_at", "updated_at"):
        def keyfn(b):
            v = b.get(sort) or ""
            return v
    else:
        def keyfn(b):
            oi = b.get("order_index")
            return oi if isinstance(oi, int) else -1

    rows.sort(key=keyfn, reverse=reverse)

    total = len(rows)
    page_rows = rows[offset:offset + limit]
    next_offset = offset + len(page_rows)
    has_more = next_offset < total
    next_cursor = f"v1:{next_offset}" if has_more else None

    _log("OK")
    return {
        "object": "list",
        "data": page_rows,
        "graph_id": graphId,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def createBlock(graphId, pageId, contentMarkdown, orderIndex, parentBlockId=None, properties=None, status=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "createBlock"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _append_log(status_code, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rql_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "graph_id": graphId,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _parse_iso(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return None

    def _enforce_limits():
        usage = _load("usage.json")
        if not isinstance(usage, dict):
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        per_min = usage.get("rate_limit_per_minute")
        quota_total = usage.get("quota_calls_total")
        calls_total = usage.get("calls_total")

        now_dt = datetime.datetime.now(datetime.timezone.utc)
        if isinstance(per_min, int) and per_min > 0:
            cutoff = now_dt - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs[-20000:]:
                if not isinstance(r, dict):
                    continue
                dt = _parse_iso(r.get("timestamp") or r.get("ts"))
                if dt and dt >= cutoff:
                    cnt += 1
            if cnt >= per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(quota_total, int) and quota_total >= 0:
            if not isinstance(calls_total, int):
                calls_total = 0
            if calls_total >= quota_total:
                return _err("QUOTA_EXCEEDED", "Quota exceeded")
        return None

    def _usage_bump(status_code):
        usage = _load("usage.json")
        if isinstance(usage, dict):
            usage["calls_total"] = int(usage.get("calls_total") or 0) + 1
            by_ep = usage.get("calls_by_endpoint")
            if not isinstance(by_ep, dict):
                by_ep = {}
            by_ep[endpoint] = int(by_ep.get(endpoint) or 0) + 1
            usage["calls_by_endpoint"] = by_ep
            if status_code and str(status_code).startswith("2"):
                usage["calls_succeeded"] = int(usage.get("calls_succeeded") or 0) + 1
            else:
                usage["calls_failed"] = int(usage.get("calls_failed") or 0) + 1
            _save("usage.json", usage)

    def _plaintext(md):
        if not isinstance(md, str):
            return ""
        txt = re.sub(r"\[\[([^\]]+)\]\]", r"\1", md)
        txt = re.sub(r"#([A-Za-z0-9_\-/]+)", r"\1", txt)
        txt = re.sub(r"`([^`]+)`", r"\1", txt)
        txt = re.sub(r"[*_~]", "", txt)
        txt = re.sub(r"\s+", " ", txt).strip()
        return txt

    def _norm_title(t):
        return " ".join(str(t).strip().lower().split())

    def _extract_refs(md):
        # return list of (link_type, target_title_norm, anchor_text)
        out = []
        if not isinstance(md, str) or not md:
            return out
        for m in re.finditer(r"\[\[([^\]]+)\]\]", md):
            raw = m.group(1).strip()
            if raw:
                out.append(("wikilink", _norm_title(raw), raw))
        for m in re.finditer(r"(?<!\w)#([A-Za-z0-9_\-/]+)", md):
            raw = m.group(1).strip()
            if raw:
                out.append(("tag", _norm_title(raw), "#" + raw))
        # property:: Value
        for m in re.finditer(r"(?m)^\s*([A-Za-z0-9_\-]+)::\s*(.+?)\s*$", md):
            raw = m.group(1).strip()
            if raw:
                out.append(("property", _norm_title(raw), raw + "::"))
        return out

    # Validate
    if not isinstance(graphId, str) or not re.match(r"^lsg_[0-9A-Za-z]+$", graphId):
        err = _err("VALIDATION_ERROR", "graphId is malformed.", field="graphId")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    if not isinstance(pageId, str):
        err = _err("VALIDATION_ERROR", "pageId must be a string.", field="pageId")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err
    # Relax: only reject clearly invalid, otherwise allow and resolve NOT_FOUND
    if not re.match(r"^[A-Za-z0-9_:-]{6,}$", pageId):
        err = _err("VALIDATION_ERROR", "pageId is malformed.", field="pageId")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    if parentBlockId is not None:
        if not isinstance(parentBlockId, str):
            err = _err("VALIDATION_ERROR", "parentBlockId must be a string.", field="parentBlockId")
            _append_log("400", {"error": err["error"]})
            _usage_bump("400")
            return err
        if not re.match(r"^[A-Za-z0-9_:-]{6,}$", parentBlockId):
            err = _err("VALIDATION_ERROR", "parentBlockId is malformed.", field="parentBlockId")
            _append_log("400", {"error": err["error"]})
            _usage_bump("400")
            return err

    if not isinstance(contentMarkdown, str):
        err = _err("VALIDATION_ERROR", "contentMarkdown must be a string.", field="contentMarkdown")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    if not isinstance(orderIndex, int) or orderIndex < 0:
        err = _err("VALIDATION_ERROR", "orderIndex must be an integer >= 0.", field="orderIndex")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    if properties is None:
        properties = {}
    if not isinstance(properties, dict):
        err = _err("VALIDATION_ERROR", "properties must be an object.", field="properties")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in ("active", "deleted"):
        err = _err("VALIDATION_ERROR", "status must be 'active' or 'deleted'.", field="status")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err
    if status != "active":
        err = _err("VALIDATION_ERROR", "Blocks must be created with status='active'.", field="status")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    lim_err = _enforce_limits()
    if lim_err:
        _append_log("429", {"error": lim_err["error"]})
        _usage_bump("429")
        return lim_err

    graphs = _load("graphs.json")
    pages = _load("pages.json")
    blocks = _load("blocks.json")
    page_links = _load("page_links.json")

    # Verify graph exists
    graph_row = None
    if isinstance(graphs, list):
        for g in graphs:
            if isinstance(g, dict) and g.get("id") == graphId:
                graph_row = g
                break
    if not graph_row:
        err = _err("NOT_FOUND", "Graph not found.", field="graphId")
        _append_log("404", {"error": err["error"]})
        _usage_bump("404")
        return err
    if graph_row.get("status") == "archived":
        err = _err("UNAUTHORIZED", "Graph is archived.")
        _append_log("401", {"error": err["error"]})
        _usage_bump("401")
        return err
    if graph_row.get("status") == "read_only":
        err = _err("INVALID_TRANSITION", "Graph is read-only; cannot create blocks.")
        _append_log("409", {"error": err["error"]})
        _usage_bump("409")
        return err

    # Verify page exists and active
    page_row = None
    if isinstance(pages, list):
        for p in pages:
            if isinstance(p, dict) and p.get("id") == pageId and p.get("graph_id") == graphId:
                page_row = p
                break
    if not page_row or page_row.get("status") != "active":
        err = _err("NOT_FOUND", "Page not found.")
        _append_log("404", {"error": err["error"]})
        _usage_bump("404")
        return err

    # Verify parent block
    if parentBlockId is not None:
        parent = None
        if isinstance(blocks, list):
            for b in blocks:
                if isinstance(b, dict) and b.get("id") == parentBlockId:
                    parent = b
                    break
        if not parent or parent.get("status") != "active" or parent.get("graph_id") != graphId:
            err = _err("NOT_FOUND", "Parent block not found.", field="parentBlockId")
            _append_log("404", {"error": err["error"]})
            _usage_bump("404")
            return err
        if parent.get("page_id") != pageId:
            err = _err("VALIDATION_ERROR", "parentBlockId must belong to the same page.", field="parentBlockId")
            _append_log("400", {"error": err["error"]})
            _usage_bump("400")
            return err

    # Uniqueness: (page_id, parent_block_id, order_index) where status='active'
    if isinstance(blocks, list):
        for b in blocks:
            if not isinstance(b, dict):
                continue
            if b.get("status") != "active":
                continue
            if b.get("graph_id") != graphId or b.get("page_id") != pageId:
                continue
            if (b.get("parent_block_id") or None) != (parentBlockId or None):
                continue
            if int(b.get("order_index") or -1) == orderIndex:
                err = _err("CONFLICT", "orderIndex collides with an existing active sibling.", field="orderIndex")
                _append_log("409", {"error": err["error"]})
                _usage_bump("409")
                return err

    now = _now_iso()
    new_id = "lsb_" + secrets.token_hex(12).upper()
    new_block = {
        "id": new_id,
        "graph_id": graphId,
        "page_id": pageId,
        "parent_block_id": parentBlockId,
        "order_index": orderIndex,
        "content_markdown": contentMarkdown,
        "content_plaintext": _plaintext(contentMarkdown),
        "properties": properties,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }

    if not isinstance(blocks, list):
        blocks = []
    blocks.append(new_block)
    _save("blocks.json", blocks)

    # Ensure link targets exist as pages (create if absent)
    def _ensure_page_by_title_norm(tnorm, display_title):
        nonlocal pages
        # find active page with title_norm
        for p in pages if isinstance(pages, list) else []:
            if isinstance(p, dict) and p.get("graph_id") == graphId and p.get("status") == "active" and p.get("title_norm") == tnorm:
                return p
        # if exists but archived, allow linking to it (still a page), but backlinks later require active
        for p in pages if isinstance(pages, list) else []:
            if isinstance(p, dict) and p.get("graph_id") == graphId and p.get("title_norm") == tnorm and p.get("status") != "deleted":
                return p
        # create new page
        pid = "lsp_" + secrets.token_hex(12).upper()
        newp = {
            "id": pid,
            "graph_id": graphId,
            "title": display_title,
            "title_norm": tnorm,
            "is_journal": False,
            "journal_date": None,
            "properties": {},
            "content_plaintext": "",
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        if not isinstance(pages, list):
            pages = []
        pages.append(newp)
        _save("pages.json", pages)
        return newp

    # Upsert page_links for this block; delete stale edges for this block first (for uniqueness)
    if not isinstance(page_links, list):
        page_links = []
    page_links = [l for l in page_links if not (isinstance(l, dict) and l.get("graph_id") == graphId and l.get("source_block_id") == new_id)]
    refs = _extract_refs(contentMarkdown)
    seen = set()
    for lt, tnorm, anchor in refs:
        if not tnorm:
            continue
        tgt_page = _ensure_page_by_title_norm(tnorm, tnorm)
        key = (graphId, new_id, tgt_page.get("id"), lt)
        if key in seen:
            continue
        seen.add(key)
        # uniqueness per schema
        lrow = {
            "id": "lsl_" + secrets.token_hex(12).upper(),
            "graph_id": graphId,
            "source_page_id": pageId,
            "source_block_id": new_id,
            "target_page_id": tgt_page.get("id"),
            "link_type": lt,
            "anchor_text": anchor,
            "created_at": now,
            "updated_at": now
        }
        page_links.append(lrow)
    _save("page_links.json", page_links)

    # Update page plaintext + updated_at
    all_blocks = [b for b in blocks if isinstance(b, dict) and b.get("graph_id") == graphId and b.get("page_id") == pageId and b.get("status") == "active"]
    all_blocks.sort(key=lambda b: (int(b.get("order_index") or 0), b.get("id") or ""))
    joined = "\n".join([(b.get("content_plaintext") or "") for b in all_blocks]).strip()
    # write through page row
    page_updated = False
    for p in pages if isinstance(pages, list) else []:
        if isinstance(p, dict) and p.get("id") == pageId:
            p["content_plaintext"] = joined
            p["updated_at"] = now
            page_updated = True
            break
    if page_updated:
        _save("pages.json", pages)

    _append_log("201", {"block_id": new_id, "page_id": pageId})
    _usage_bump("201")
    return {"block": new_block}

def updatePage(graphId, pageId, title=None, properties=None, contentMarkdown=None, status=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "updatePage"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return None

    def _append_log(status_code, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rql_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "graph_id": graphId,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        usage = _load("usage.json")
        if not isinstance(usage, dict):
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        per_min = usage.get("rate_limit_per_minute")
        quota_total = usage.get("quota_calls_total")
        calls_total = usage.get("calls_total")

        now_dt = datetime.datetime.now(datetime.timezone.utc)
        if isinstance(per_min, int) and per_min > 0:
            cutoff = now_dt - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs[-20000:]:
                if not isinstance(r, dict):
                    continue
                dt = _parse_iso(r.get("timestamp") or r.get("ts"))
                if dt and dt >= cutoff:
                    cnt += 1
            if cnt >= per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(quota_total, int) and quota_total >= 0:
            if not isinstance(calls_total, int):
                calls_total = 0
            if calls_total >= quota_total:
                return _err("QUOTA_EXCEEDED", "Quota exceeded")
        return None

    def _usage_bump(status_code):
        usage = _load("usage.json")
        if isinstance(usage, dict):
            usage["calls_total"] = int(usage.get("calls_total") or 0) + 1
            by_ep = usage.get("calls_by_endpoint")
            if not isinstance(by_ep, dict):
                by_ep = {}
            by_ep[endpoint] = int(by_ep.get(endpoint) or 0) + 1
            usage["calls_by_endpoint"] = by_ep
            if status_code and str(status_code).startswith("2"):
                usage["calls_succeeded"] = int(usage.get("calls_succeeded") or 0) + 1
            else:
                usage["calls_failed"] = int(usage.get("calls_failed") or 0) + 1
            _save("usage.json", usage)

    def _norm_title(t):
        return " ".join(str(t).strip().lower().split())

    def _plaintext(md):
        if not isinstance(md, str):
            return ""
        txt = re.sub(r"\[\[([^\]]+)\]\]", r"\1", md)
        txt = re.sub(r"#([A-Za-z0-9_\-/]+)", r"\1", txt)
        txt = re.sub(r"`([^`]+)`", r"\1", txt)
        txt = re.sub(r"[*_~]", "", txt)
        txt = re.sub(r"\s+", " ", txt).strip()
        return txt

    # Validate
    if not isinstance(graphId, str) or not re.match(r"^lsg_[0-9A-Za-z]+$", graphId):
        err = _err("VALIDATION_ERROR", "graphId is malformed.", field="graphId")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    if not isinstance(pageId, str):
        err = _err("VALIDATION_ERROR", "pageId must be a string.", field="pageId")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err
    # Relax strict lsp_ requirement to avoid rejecting real datastore-consistent calls; resolve NOT_FOUND later
    if not re.match(r"^[A-Za-z0-9_:-]{6,}$", pageId):
        err = _err("VALIDATION_ERROR", "pageId is malformed.", field="pageId")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    if title is not None and not isinstance(title, str):
        err = _err("VALIDATION_ERROR", "title must be a string.", field="title")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err
    if properties is not None and not isinstance(properties, dict):
        err = _err("VALIDATION_ERROR", "properties must be an object.", field="properties")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err
    if contentMarkdown is not None and not isinstance(contentMarkdown, str):
        err = _err("VALIDATION_ERROR", "contentMarkdown must be a string.", field="contentMarkdown")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            err = _err("VALIDATION_ERROR", "status must be one of 'active','archived','deleted'.", field="status")
            _append_log("400", {"error": err["error"]})
            _usage_bump("400")
            return err

    lim_err = _enforce_limits()
    if lim_err:
        _append_log("429", {"error": lim_err["error"]})
        _usage_bump("429")
        return lim_err

    graphs = _load("graphs.json")
    pages = _load("pages.json")
    blocks = _load("blocks.json")
    page_links = _load("page_links.json")

    graph_row = None
    if isinstance(graphs, list):
        for g in graphs:
            if isinstance(g, dict) and g.get("id") == graphId:
                graph_row = g
                break
    if not graph_row:
        err = _err("NOT_FOUND", "Graph not found.", field="graphId")
        _append_log("404", {"error": err["error"]})
        _usage_bump("404")
        return err

    if graph_row.get("status") == "archived":
        err = _err("UNAUTHORIZED", "Graph is archived.")
        _append_log("401", {"error": err["error"]})
        _usage_bump("401")
        return err

    # Find page
    page_idx = None
    page_row = None
    if isinstance(pages, list):
        for i, p in enumerate(pages):
            if isinstance(p, dict) and p.get("id") == pageId and p.get("graph_id") == graphId:
                page_idx = i
                page_row = p
                break
    if not page_row:
        err = _err("NOT_FOUND", "Page not found.")
        _append_log("404", {"error": err["error"]})
        _usage_bump("404")
        return err

    if graph_row.get("status") == "read_only":
        # allow status changes? keep strict: no mutations
        err = _err("INVALID_TRANSITION", "Graph is read-only; cannot update pages.")
        _append_log("409", {"error": err["error"]})
        _usage_bump("409")
        return err

    # Lifecycle transition validation for page
    if status is not None:
        cur = page_row.get("status")
        allowed = {
            "active": {"archived", "deleted"},
            "archived": {"active", "deleted"},
            "deleted": set()
        }
        if cur not in allowed or status == cur:
            # setting same status is idempotent
            pass
        else:
            if status not in allowed.get(cur, set()):
                err = _err("INVALID_TRANSITION", f"Illegal status transition {cur}→{status}.", field="status")
                _append_log("409", {"error": err["error"]})
                _usage_bump("409")
                return err

    # Title uniqueness (graph_id, title_norm) where status != 'deleted'
    if title is not None:
        new_norm = _norm_title(title)
        for p in pages if isinstance(pages, list) else []:
            if not isinstance(p, dict):
                continue
            if p.get("graph_id") != graphId:
                continue
            if p.get("id") == pageId:
                continue
            if p.get("status") == "deleted":
                continue
            if p.get("title_norm") == new_norm:
                err = _err("CONFLICT", "title must be unique within graph (case/space-insensitive).", field="title")
                _append_log("409", {"error": err["error"]})
                _usage_bump("409")
                return err

    # Mutate
    now = _now_iso()
    changed = False

    if title is not None:
        page_row["title"] = title
        page_row["title_norm"] = _norm_title(title)
        changed = True

    if properties is not None:
        # Replace (server default)
        page_row["properties"] = properties
        changed = True

    if status is not None and status != page_row.get("status"):
        page_row["status"] = status
        changed = True

    if contentMarkdown is not None:
        # Ingest as "replace page content": store as a single top-level block (common simplification),
        # and recompute page plaintext from active blocks after upserting that block.
        if not isinstance(blocks, list):
            blocks = []
        # create/replace a special synthetic top-level block for page-level content
        existing = None
        for b in blocks:
            if isinstance(b, dict) and b.get("graph_id") == graphId and b.get("page_id") == pageId and b.get("parent_block_id") is None and b.get("order_index") == 0 and b.get("properties", {}).get("_page_content") is True:
                existing = b
                break
        if existing:
            existing["content_markdown"] = contentMarkdown
            existing["content_plaintext"] = _plaintext(contentMarkdown)
            existing["updated_at"] = now
        else:
            # ensure no collision at order_index 0 among active top-level blocks; if collides, choose next
            used = set()
            for b in blocks:
                if isinstance(b, dict) and b.get("graph_id") == graphId and b.get("page_id") == pageId and b.get("status") == "active" and b.get("parent_block_id") is None:
                    try:
                        used.add(int(b.get("order_index") or 0))
                    except Exception:
                        pass
            oi = 0
            while oi in used:
                oi += 1
            blocks.append({
                "id": "lsb_" + secrets.token_hex(12).upper(),
                "graph_id": graphId,
                "page_id": pageId,
                "parent_block_id": None,
                "order_index": oi,
                "content_markdown": contentMarkdown,
                "content_plaintext": _plaintext(contentMarkdown),
                "properties": {"_page_content": True},
                "status": "active",
                "created_at": now,
                "updated_at": now
            })
        _save("blocks.json", blocks)

        # Recompute page plaintext from active blocks
        active_blocks = [b for b in blocks if isinstance(b, dict) and b.get("graph_id") == graphId and b.get("page_id") == pageId and b.get("status") == "active"]
        active_blocks.sort(key=lambda b: (int(b.get("order_index") or 0), b.get("id") or ""))
        page_row["content_plaintext"] = "\n".join([(b.get("content_plaintext") or "") for b in active_blocks]).strip()
        changed = True
        # page_links maintenance for "affected blocks": do nothing here beyond leaving block-level tools to manage.
        # (Real system would re-extract; kept minimal to avoid fabricating edges.)

    if changed:
        page_row["updated_at"] = now
        pages[page_idx] = page_row
        _save("pages.json", pages)
    else:
        # no effect -> return without success
        err = _err("CONFLICT", "No changes to apply.")
        _append_log("409", {"error": err["error"]})
        _usage_bump("409")
        return err

    _append_log("200", {"page_id": pageId})
    _usage_bump("200")
    return {"page": page_row}

