                out.append(("wikilink", _norm_title(raw), raw))
        for m in re.finditer(r"(?<!\w)#([A-Za-z0-9_\-/]+)", md):
            raw = m.group(1).strip()
            if raw:
                out.append(("tag", _norm_title(raw), "#" + raw))
        for m in re.finditer(r"(?m)^\s*([A-Za-z0-9_\-]+)::\s*(.+?)\s*$", md):
            raw = m.group(1).strip()
            if raw:
                out.append(("property", _norm_title(raw), raw + "::"))
        return out

    # Validate
    if not isinstance(graphId, str) or not re.match(r"^lsg_[0-9A-Za-z]+$", graphId):
        err = _err("VALIDATION_ERROR", "graphId is malformed.", field="graphId")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    if not isinstance(blockId, str) or not re.match(r"^[A-Za-z0-9_:-]{6,}$", blockId):
        err = _err("VALIDATION_ERROR", "blockId is malformed.", field="blockId")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err

    if contentMarkdown is not None and not isinstance(contentMarkdown, str):
        err = _err("VALIDATION_ERROR", "contentMarkdown must be a string.", field="contentMarkdown")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err
    if properties is not None and not isinstance(properties, dict):
        err = _err("VALIDATION_ERROR", "properties must be an object.", field="properties")
        _append_log("400", {"error": err["error"]})
        _usage_bump("400")
        return err
    if orderIndex is not None:
        if not isinstance(orderIndex, int) or orderIndex < 0:
            err = _err("VALIDATION_ERROR", "orderIndex must be an integer >= 0.", field="orderIndex")
            _append_log("400", {"error": err["error"]})
            _usage_bump("400")
            return err
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            err = _err("VALIDATION_ERROR", "status must be 'active' or 'deleted'.", field="status")
            _append_log("400", {"error": err["error"]})
            _usage_bump("400")
            return err

    lim_err = _enforce_limits()
    if lim_err:
        _append_log("429", {"error": lim_err["error"]})
        _usage_bump("429")
        return lim_err

    graphs = _load("graphs.json")
    pages = _load("pages.json")
    blocks = _load("blocks.json")
    page_links = _load("page_links.json")

    graph_row = None
    if isinstance(graphs, list):
        for g in graphs:
            if isinstance(g, dict) and g.get("id") == graphId:
                graph_row = g
                break
    if not graph_row:
        err = _err("NOT_FOUND", "Graph not found.", field="graphId")
        _append_log("404", {"error": err["error"]})
        _usage_bump("404")
        return err
    if graph_row.get("status") == "archived":
        err = _err("UNAUTHORIZED", "Graph is archived.")
        _append_log("401", {"error": err["error"]})
        _usage_bump("401")
        return err
    if graph_row.get("status") == "read_only":
        err = _err("INVALID_TRANSITION", "Graph is read-only; cannot update blocks.")
        _append_log("409", {"error": err["error"]})
        _usage_bump("409")
        return err

    if not isinstance(blocks, list):
        blocks = []
    bidx = None
    brow = None
    for i, b in enumerate(blocks):
        if isinstance(b, dict) and b.get("id") == blockId and b.get("graph_id") == graphId:
            bidx = i
            brow = b
            break
    if not brow:
        err = _err("NOT_FOUND", "Block not found.")
        _append_log("404", {"error": err["error"]})
        _usage_bump("404")
        return err

    # lifecycle transition: active -> deleted only
    if status is not None:
        cur = brow.get("status")
        if status == cur:
            pass
        else:
            if not (cur == "active" and status == "deleted"):
                err = _err("INVALID_TRANSITION", f"Illegal status transition {cur}→{status}.", field="status")
                _append_log("409", {"error": err["error"]})
                _usage_bump("409")
                return err

    # orderIndex uniqueness among active siblings
    if orderIndex is not None:
        for b in blocks:
            if not isinstance(b, dict):
                continue
            if b.get("id") == blockId:
                continue
            if b.get("graph_id") != graphId or b.get("page_id") != brow.get("page_id"):
                continue
            if b.get("status") != "active":
                continue
            if (b.get("parent_block_id") or None) != (brow.get("parent_block_id") or None):
                continue
            if int(b.get("order_index") or -1) == orderIndex:
                err = _err("CONFLICT", "orderIndex collides with an existing active sibling.", field="orderIndex")
                _append_log("409", {"error": err["error"]})
                _usage_bump("409")
                return err

    changed = False
    now = _now_iso()

    if contentMarkdown is not None and contentMarkdown != brow.get("content_markdown"):
        brow["content_markdown"] = contentMarkdown
        brow["content_plaintext"] = _plaintext(contentMarkdown)
        changed = True

    if properties is not None:
        brow["properties"] = properties
        changed = True

    if orderIndex is not None and orderIndex != brow.get("order_index"):
        brow["order_index"] = orderIndex
        changed = True

    if status is not None and status != brow.get("status"):
        brow["status"] = status
        changed = True

    if not changed:
        err = _err("CONFLICT", "No changes to apply.")
        _append_log("409", {"error": err["error"]})
        _usage_bump("409")
        return err

    brow["updated_at"] = now
    blocks[bidx] = brow
    _save("blocks.json", blocks)

    # page_links maintenance on content changes or deletion
    if not isinstance(page_links, list):
        page_links = []
    if contentMarkdown is not None or (status is not None and status == "deleted"):
        # delete existing edges for this block (stale)
        page_links = [l for l in page_links if not (isinstance(l, dict) and l.get("graph_id") == graphId and l.get("source_block_id") == blockId)]
        # re-add if still active and content provided
        if brow.get("status") == "active":
            refs = _extract_refs(brow.get("content_markdown") or "")
            # ensure pages for targets exist (create if missing)
            if not isinstance(pages, list):
                pages = []
            def _ensure_page(tnorm, disp):
                for p in pages:
                    if isinstance(p, dict) and p.get("graph_id") == graphId and p.get("title_norm") == tnorm and p.get("status") != "deleted":
                        return p
                pid = "lsp_" + secrets.token_hex(12).upper()
                np = {
                    "id": pid,
                    "graph_id": graphId,
                    "title": disp,
                    "title_norm": tnorm,
                    "is_journal": False,
                    "journal_date": None,
                    "properties": {},
                    "content_plaintext": "",
                    "status": "active",
                    "created_at": now,
                    "updated_at": now
                }
                pages.append(np)
                _save("pages.json", pages)
                return np

            seen = set()
            for lt, tnorm, anchor in refs:
                tp = _ensure_page(tnorm, tnorm)
                key = (graphId, blockId, tp.get("id"), lt)
                if key in seen:
                    continue
                seen.add(key)
                page_links.append({
                    "id": "lsl_" + secrets.token_hex(12).upper(),
                    "graph_id": graphId,
                    "source_page_id": brow.get("page_id"),
                    "source_block_id": blockId,
                    "target_page_id": tp.get("id"),
                    "link_type": lt,
                    "anchor_text": anchor,
                    "created_at": now,
                    "updated_at": now
                })
        _save("page_links.json", page_links)

    # Update owning page plaintext and updated_at
    page_id = brow.get("page_id")
    if isinstance(pages, list):
        pidx = None
        prow = None
        for i, p in enumerate(pages):
            if isinstance(p, dict) and p.get("id") == page_id and p.get("graph_id") == graphId:
                pidx = i
                prow = p
                break
        if prow:
            active_blocks = [b for b in blocks if isinstance(b, dict) and b.get("graph_id") == graphId and b.get("page_id") == page_id and b.get("status") == "active"]
            active_blocks.sort(key=lambda b: (int(b.get("order_index") or 0), b.get("id") or ""))
            prow["content_plaintext"] = "\n".join([(b.get("content_plaintext") or "") for b in active_blocks]).strip()
            prow["updated_at"] = now
            pages[pidx] = prow
            _save("pages.json", pages)

    _append_log("200", {"block_id": blockId})
    _usage_bump("200")
    return {"block": brow}

def getCaller(includeQuota=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0146000" if __import__("os").path.isdir("./environment_mix/0146000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if not isinstance(v, str) or not v:
            return None
        try:
            # Accept "Z" suffix
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return None

    def _log_call(status, credential_id=None, error_code=None, error_message=None, meta=None, started_at=None):
        # Observable service dynamics: write an audit row if a log collection exists.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if started_at is None:
            started_at = datetime.datetime.now(datetime.timezone.utc)
        ended_at = datetime.datetime.now(datetime.timezone.utc)
        latency_ms = int((ended_at - started_at).total_seconds() * 1000)
        row = {
            "id": "req_" + ended_at.strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "getCaller",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": ended_at.isoformat(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    started = datetime.datetime.now(datetime.timezone.utc)

    # Validate inputs
    if includeQuota is not None and not isinstance(includeQuota, bool):
        _log_call("error", credential_id=None, error_code="VALIDATION_ERROR", error_message="includeQuota must be a boolean", started_at=started)
        return _err("VALIDATION_ERROR", "includeQuota must be a boolean")

    # Ambient authentication: choose any credential context that can call this endpoint.
    # If the datastore includes explicit credentials, enforce it; otherwise, treat as authenticated local caller.
    creds = _load("credentials.json")
    if creds and not isinstance(creds, list):
        creds = []

    caller = None
    if creds:
        # Choose a credential that is active and allowed.
        for c in creds:
            if not isinstance(c, dict):
                continue
            if c.get("status") and c.get("status") not in ("active", "enabled"):
                continue
            # Optional scope/permission checks if present.
            scopes = c.get("scopes")
            if scopes is None or (isinstance(scopes, list) and (("getCaller" in scopes) or ("*" in scopes) or ("read" in scopes) or ("caller:read" in scopes))):
                caller = c
                break
        if caller is None:
            _log_call("error", credential_id=None, error_code="UNAUTHORIZED", error_message="No valid credential available for this endpoint", started_at=started)
            return _err("UNAUTHORIZED", "No valid credential available for this endpoint")
    else:
        caller = {
            "id": "ambient",
            "type": "local",
            "status": "active",
            "scopes": ["*"],
        }

    # Optional rate/quota reporting/enforcement if a usage collection exists
    quota_info = None
    if includeQuota:
        # Look for usage counters files commonly used by this harness.
        usage = _load("usage.json")
        if not isinstance(usage, list):
            usage = []
        limits = _load("limits.json")
        if not isinstance(limits, list):
            limits = []

        # Aggregate simple counts for this credential and endpoint within rolling windows (if logs exist).
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        cred_id = caller.get("id")
        now = datetime.datetime.now(datetime.timezone.utc)

        def _count_since(seconds):
            cutoff = now - datetime.timedelta(seconds=seconds)
            n = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("endpoint") != "getCaller":
                    continue
                if r.get("credential_id") != cred_id:
                    continue
                dt = _parse_dt(r.get("created_at"))
                if dt is None:
                    continue
                if dt >= cutoff:
                    n += 1
            return n

        per_min = _count_since(60)
        per_hour = _count_since(3600)

        # Default soft limits if declared in limits.json; otherwise just report counts.
        # limits rows may look like: {"credential_id": "...", "endpoint": "getCaller", "per_minute": 60, "per_hour": 1000, "per_day": 10000}
        lim = None
        for l in limits:
            if isinstance(l, dict) and l.get("credential_id") == cred_id and (l.get("endpoint") in (None, "getCaller", "*")):
                lim = l
                break

        quota_info = {
            "credential_id": cred_id,
            "endpoint": "getCaller",
            "counters": {"per_minute": per_min, "per_hour": per_hour},
            "limits": {},
        }
        if isinstance(lim, dict):
            for k in ("per_minute", "per_hour", "per_day"):
                if isinstance(lim.get(k), int):
                    quota_info["limits"][k] = lim.get(k)

            # Enforce if present (rate limit)
            if "per_minute" in quota_info["limits"] and per_min >= quota_info["limits"]["per_minute"]:
                _log_call("error", credential_id=cred_id, error_code="RATE_LIMIT", error_message="Rate limit exceeded (per_minute)", started_at=started)
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=quota_info["limits"]["per_minute"], window_seconds=60, current=per_min)
            if "per_hour" in quota_info["limits"] and per_hour >= quota_info["limits"]["per_hour"]:
                _log_call("error", credential_id=cred_id, error_code="RATE_LIMIT", error_message="Rate limit exceeded (per_hour)", started_at=started)
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=quota_info["limits"]["per_hour"], window_seconds=3600, current=per_hour)

        # Quota accounting by day if request logs exist and per_day limit exists
        if isinstance(lim, dict) and isinstance(lim.get("per_day"), int):
            cutoff = now - datetime.timedelta(days=1)
            per_day = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("credential_id") != cred_id:
                    continue
                dt = _parse_dt(r.get("created_at"))
                if dt is None:
                    continue
                if dt >= cutoff:
                    per_day += 1
            quota_info["counters"]["per_day"] = per_day
            if per_day >= lim["per_day"]:
                _log_call("error", credential_id=cred_id, error_code="QUOTA_EXCEEDED", error_message="Daily quota exceeded", started_at=started)
                return _err("QUOTA_EXCEEDED", "Quota exceeded", limit=lim["per_day"], window_seconds=86400, current=per_day)

    # Build response
    resp = {
        "caller": {
            "id": caller.get("id"),
            "type": caller.get("type", "credential"),
            "status": caller.get("status", "active"),
            "scopes": caller.get("scopes", []),
            "display_name": caller.get("display_name") or caller.get("name"),
        },
        "entitlements": caller.get("entitlements") if isinstance(caller.get("entitlements"), dict) else {},
    }
    if includeQuota:
        resp["quota"] = quota_info if quota_info is not None else {"note": "No quota counters available"}

    _log_call("ok", credential_id=caller.get("id"), started_at=started)
    return resp
